css:
:root{
  --deep:#0F3D2E; --forest:#1E5631; --mid:#2E7D51; --leaf:#8CC63F; --leaf-soft:#E8F5E0;
  --gold:#B08A3E; --gold-soft:#F4EBD6;
  --ivory:#F5F8F3; --paper:#FFFFFF; --line:#DCE7DA; --line2:#EDF3EA;
  --ink:#1B2B24; --ink2:#3D5148; --muted:#6E8378;
  --pos:#1E7A4C; --posbg:#E7F5EC; --warn:#B7791F; --warnbg:#FBF2E0; --alert:#B0392F; --alertbg:#FBEAE8;
  --blue:#2A5D7C; --bluebg:#E8F1F6; --plum:#6B4A75; --plumbg:#F2EBF4;
  --radius:12px; --shadow:0 1px 2px rgba(15,61,46,.06),0 6px 18px rgba(15,61,46,.07);
  --sbw:264px;
}
*{box-sizing:border-box;-webkit-font-smoothing:antialiased}
html,body{margin:0;padding:0}
body{
  font-family:"Segoe UI",Inter,system-ui,-apple-system,"Helvetica Neue",Arial,sans-serif;
  font-size:14px; color:var(--ink); background:var(--ivory);
  background-image:radial-gradient(1200px 500px at 12% -10%, #EAF4E6 0%, transparent 60%),
                   radial-gradient(900px 420px at 100% 0%, #F3F0E4 0%, transparent 55%);
  background-attachment:fixed;
}
h1,h2,h3,h4,.serif{font-family:Georgia,"Times New Roman",serif}
button,input,select{font-family:inherit}
::-webkit-scrollbar{width:9px;height:9px}
::-webkit-scrollbar-thumb{background:#C9DCC8;border-radius:8px}
::-webkit-scrollbar-track{background:transparent}

.topbar{position:sticky;top:0;z-index:60;background:linear-gradient(180deg,#0F3D2E 0%,#164733 100%);
  border-bottom:2px solid var(--gold); box-shadow:0 2px 14px rgba(15,61,46,.25)}
.tb-in{display:flex;align-items:center;gap:16px;padding:9px 18px}
.brandmark{width:44px;height:44px;border-radius:10px;background:linear-gradient(160deg,#FFFFFF,#EAF4E6);
  display:flex;align-items:center;justify-content:center;flex:0 0 auto;border:1px solid rgba(176,138,62,.5)}
.brandmark span{font-family:Inter,"Segoe UI",Arial,sans-serif;font-weight:700;font-size:20px;color:var(--forest);letter-spacing:.5px;position:relative}
.brandmark span:after{content:"";position:absolute;top:-4px;right:-7px;width:8px;height:8px;border-radius:50% 0 50% 50%;
  background:var(--leaf);transform:rotate(20deg)}
.brandtxt{
    display:flex !important;
    align-items:center;
    gap:14px
}
.test-badge{background:rgba(242,198,76,.16);border:1px solid rgba(242,198,76,.5);color:#F2C64C;
  font-size:11px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;padding:3px 10px;border-radius:20px;white-space:nowrap}
.brandtxt .cn{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:19px;font-weight:700;color:#fff;letter-spacing:.4px}
.brandtxt .cs{font-size:11.5px;color:#BFE0C4;letter-spacing:2.2px;text-transform:uppercase;margin-top:2px}
.pulse{
    display:none;
}
.pulse .pi{padding:2px 15px;border-right:1px dashed rgba(255,255,255,.14);white-space:nowrap}
.pulse .pi:last-child{border-right:0}
.pulse .pl{font-size:10.5px;letter-spacing:1.1px;text-transform:uppercase;color:#9CC7A6}
.pulse .pv{font-size:15px;font-weight:700;color:#fff;font-family:Inter,"Segoe UI",Arial,sans-serif}
.pulse .pv i{font-style:normal;font-size:11px;margin-left:4px}
.up{color:#A6E29E}.down{color:#F0A79E}
.tb-ico{width:34px;height:34px;border-radius:9px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.07);
  color:#DFF0E2;display:flex;align-items:center;justify-content:center;cursor:pointer;position:relative;font-size:15px}
.tb-ico:hover{background:rgba(255,255,255,.16)}
.tb-ico b{position:absolute;top:-6px;right:-6px;background:var(--gold);color:#231a06;font-size:10px;border-radius:9px;padding:1px 5px}
.who{display:flex;align-items:center;gap:10px;padding-left:14px;border-left:1px solid rgba(255,255,255,.14)}
.who img{width:38px;height:38px;border-radius:50%;border:2px solid var(--gold)}
.who .wn{font-size:13.5px;font-weight:600;color:#fff;line-height:1.2}
.who .wr{font-size:11px;color:#A9CDB2;letter-spacing:.6px}


.filterwrap.hidden{display:none}
.frow{display:flex;gap:12px;align-items:flex-end;padding:10px 18px 0 18px;flex-wrap:wrap}
.frow:not(.two) .fld{flex:1 1 0;min-width:150px}
.frow.two{padding:9px 18px 11px 18px;align-items:center}
.fld{display:flex;flex-direction:column;gap:4px}
.fld label{font-size:11px;letter-spacing:1px;text-transform:uppercase;color:var(--muted);font-weight:600}
.fld select,.fld input{height:34px;border:1px solid var(--line);border-radius:8px;padding:0 10px;font-size:14px;
  background:#fff;color:var(--ink);min-width:150px;outline:none}
.fld select:focus,.fld input:focus{border-color:var(--mid);box-shadow:0 0 0 3px rgba(46,125,81,.12)}
.btn{height:34px;border-radius:8px;border:1px solid var(--line);background:#fff;color:var(--ink2);padding:0 15px;
  font-size:13.5px;cursor:pointer;display:inline-flex;align-items:center;gap:7px;font-weight:600;white-space:nowrap}
.btn:hover{border-color:var(--mid);color:var(--forest);background:#F6FBF4}
.btn.primary{background:linear-gradient(180deg,#2E7D51,#1E5631);color:#fff;border-color:#1E5631}
.btn.primary:hover{background:linear-gradient(180deg,#358F5C,#22633A);color:#fff}
.btn.gold{background:linear-gradient(180deg,#C79A45,#A87F33);color:#fff;border-color:#9C742C}
.btn.gold:hover{color:#fff;background:linear-gradient(180deg,#D2A54D,#B0873A)}
.btn.sm{height:28px;font-size:12.5px;padding:0 11px}
.btn:disabled{opacity:.42;cursor:not-allowed}
.reopen{display:none;justify-content:center;position:sticky;top:62px;z-index:54}
.reopen.on{display:flex}
.reopen button{width:96px;height:20px;border:1px solid var(--line);border-top:0;background:#fff;color:var(--forest);
  border-radius:0 0 12px 12px;cursor:pointer;font-size:12px;box-shadow:0 4px 10px rgba(15,61,46,.08)}
.chipline{display:flex;gap:7px;flex-wrap:wrap;align-items:center;padding:0 18px 9px 18px}
.chip{font-size:11.5px;background:var(--leaf-soft);color:var(--forest);border:1px solid #CFE6C3;border-radius:20px;padding:2px 10px;font-weight:600}
.chip.g{background:var(--gold-soft);border-color:#E4D3A9;color:#7C5E1E}

.shell{display:flex;align-items:flex-start;gap:0}
.sidebar.mini{width:60px;flex:0 0 60px}
.sb-top{padding:10px 10px 8px 10px;border-bottom:1px solid rgba(255,255,255,.09);display:flex;gap:7px;align-items:center}
.sb-search{flex:1;height:30px;border-radius:7px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.08);
  color:#EAF5EA;padding:0 10px;font-size:13px;outline:none;min-width:0}
.sb-search::placeholder{color:#8FB79A}
.sidebar.mini .sb-search{display:none}
.sb-toggle{width:30px;height:30px;flex:0 0 30px;border-radius:7px;border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.08);color:#CFE8D2;cursor:pointer;font-size:14px}
.sb-close{display:none;width:30px;height:30px;flex:0 0 30px;border-radius:7px;border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.08);color:#FFD9D2;cursor:pointer;font-size:15px;align-items:center;justify-content:center}
.sb-close:hover{background:rgba(176,57,47,.4)}
.sb-scroll{flex:1;overflow-y:auto;overflow-x:hidden;padding:8px 0 14px 0}
.grp{padding:11px 14px 5px 14px;font-size:10.5px;letter-spacing:1.6px;text-transform:uppercase;color:#7FAE8C;font-weight:700}
.sidebar.mini .grp{text-align:center;font-size:9px;letter-spacing:0;padding:9px 0 4px 0;color:#5E8E6C}
.mi{display:flex;align-items:center;gap:10px;padding:8px 12px;margin:1px 8px;border-radius:9px;cursor:pointer;
  color:#D3E7D6;font-size:13.5px;position:relative;user-select:none}
.mi:hover{background:rgba(255,255,255,.09);color:#fff}
.mi.on{background:linear-gradient(90deg,rgba(140,198,63,.22),rgba(140,198,63,.05));color:#fff;
  box-shadow:inset 3px 0 0 var(--leaf)}
.mi .ic{width:26px;height:26px;flex:0 0 26px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:14px}
.mi .tx{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mi .st{opacity:.28;font-size:13px;flex:0 0 auto}
.mi .st.fav{opacity:1;color:#F2C64C}
.mi .st:hover{opacity:1}
.mi .bdg{background:var(--gold);color:#22190a;border-radius:9px;font-size:10px;padding:0 6px;font-weight:700}
.sidebar.mini .tx,.sidebar.mini .st,.sidebar.mini .bdg{display:none}
.sidebar.mini .mi{justify-content:center;padding:9px 0;margin:2px 7px}
.sidebar.mini .mi:hover:after{content:attr(data-tip);position:absolute;left:56px;background:#0B2A1D;color:#EAF5EA;
  padding:5px 10px;border-radius:7px;font-size:12.5px;white-space:nowrap;border:1px solid rgba(255,255,255,.14);z-index:99}
.sb-foot{padding:9px 12px;border-top:1px solid rgba(255,255,255,.09);color:#88B394;font-size:11px;display:flex;
  align-items:center;gap:8px;justify-content:space-between}
.sidebar.mini .sb-foot span.t{display:none}
.sw{width:32px;height:17px;border-radius:20px;background:rgba(255,255,255,.2);position:relative;cursor:pointer;flex:0 0 32px}
.sw:after{content:"";position:absolute;top:2px;left:2px;width:13px;height:13px;border-radius:50%;background:#fff;transition:.18s}
.sw.on{background:var(--leaf)}.sw.on:after{left:17px}

.main{flex:1;min-width:0;padding:16px 18px 40px 18px}
.page{display:none}.page.on{display:block}
.phead{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin:2px 0 14px 0;
  padding-bottom:10px;border-bottom:1px solid var(--line)}
.phead h1{font-size:25px;margin:0;color:var(--deep);letter-spacing:.2px}
.phead .note{font-size:12.5px;color:var(--muted);margin-top:4px;max-width:820px;line-height:1.5}
.phead .rule{height:3px;width:56px;background:linear-gradient(90deg,var(--gold),#E2CB92);border-radius:3px;margin-bottom:9px}
.acts{display:flex;gap:8px;flex:0 0 auto}

.sec{background:var(--paper);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);margin-bottom:14px;overflow:hidden}
.sec>header{display:flex;align-items:center;gap:10px;padding:11px 15px;cursor:pointer;
  background:linear-gradient(180deg,#FBFDFA,#F2F8EF);border-bottom:1px solid var(--line)}
.sec>header .dot{width:9px;height:9px;border-radius:3px;background:var(--mid);flex:0 0 9px}
.sec>header h3{margin:0;font-size:17px;color:var(--deep);flex:0 0 auto}
.sec>header .sn{font-size:12px;color:var(--muted);flex:1;padding-left:6px;border-left:1px solid var(--line);margin-left:4px}
.sec>header .cv{color:var(--muted);font-size:13px;transition:.2s}
.sec.closed>header .cv{transform:rotate(-90deg)}
.sec .body{padding:14px 15px}
.sec.closed .body{display:none}
.sec.gold>header{background:linear-gradient(180deg,#FDFAF2,#F7EFDD);border-bottom-color:#E7D8B4}
.sec.gold>header .dot{background:var(--gold)}
.sec.blue>header{background:linear-gradient(180deg,#F8FBFD,#EAF2F7)}
.sec.blue>header .dot{background:var(--blue)}
.sec.plum>header{background:linear-gradient(180deg,#FBF9FC,#F1EBF4)}
.sec.plum>header .dot{background:var(--plum)}

.kgrid{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(215px,1fr))}
.kpi{background:#fff;border:1px solid var(--line);border-radius:12px;padding:13px 14px;position:relative;overflow:hidden}
.kpi:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--mid)}
.kpi.g:before{background:var(--gold)}.kpi.b:before{background:var(--blue)}.kpi.p:before{background:var(--plum)}
.kpi.a:before{background:var(--alert)}
.kpi .kl{font-size:11px;letter-spacing:1.1px;text-transform:uppercase;color:var(--muted);font-weight:700}
.kpi .kv{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:27px;font-weight:700;color:var(--deep);margin:5px 0 2px 0;line-height:1.1}
.kpi .ks{font-size:12px;color:var(--ink2)}
.kpi .kt{position:absolute;right:12px;top:12px;font-size:11.5px;font-weight:700;border-radius:20px;padding:2px 8px}
.kt.u{background:var(--posbg);color:var(--pos)} .kt.d{background:var(--alertbg);color:var(--alert)}
.kt.n{background:#F0F3F1;color:var(--muted)}
.kpi.clk{cursor:pointer}.kpi.clk:hover{border-color:var(--mid);box-shadow:0 6px 16px rgba(30,86,49,.1);transform:translateY(-1px);transition:.15s}

.tw{overflow:auto;border:1px solid var(--line);border-radius:10px;background:#fff}
table.dt{width:100%;border-collapse:collapse;font-size:13px}
table.dt th{background:linear-gradient(180deg,#F4F9F1,#E9F3E4);color:var(--deep);text-align:left;padding:8px 10px;
  font-size:11.5px;letter-spacing:.7px;text-transform:uppercase;font-weight:700;white-space:nowrap;
  border-bottom:1px solid var(--line);position:sticky;top:0;cursor:pointer;user-select:none}
table.dt th:hover{background:#E2EFDB}
table.dt th.num,table.dt td.num{text-align:right}
table.dt th:after{content:"⇅";opacity:.25;margin-left:5px;font-size:10px}
table.dt th.asc:after{content:"▲";opacity:.9}table.dt th.desc:after{content:"▼";opacity:.9}
table.dt td{padding:7px 10px;border-bottom:1px solid var(--line2);vertical-align:middle}
table.dt tbody tr:nth-child(even){background:#FBFDFA}
table.dt tbody tr:hover{background:#F1F8ED}
table.dt tbody tr.clk{cursor:pointer}
table.dt tfoot td{background:#EDF5E8;font-weight:700;color:var(--deep);border-top:1.5px solid #CFE2C6;position:sticky;bottom:0}
.d2{line-height:1.25}.d2 b{font-weight:600;font-size:13px;color:var(--ink)}
.d2 s{display:block;text-decoration:none;font-size:11.5px;color:var(--muted)}
.pill{display:inline-block;font-size:11px;font-weight:700;border-radius:20px;padding:2px 9px;white-space:nowrap}
.p-ok{background:var(--posbg);color:var(--pos)} .p-wn{background:var(--warnbg);color:var(--warn)}
.p-al{background:var(--alertbg);color:var(--alert)} .p-nu{background:#EEF2F0;color:var(--ink2)}
.p-bl{background:var(--bluebg);color:var(--blue)} .p-gd{background:var(--gold-soft);color:#7C5E1E}
.bar{height:7px;border-radius:6px;background:#EDF2EE;overflow:hidden;min-width:70px}
.bar i{display:block;height:100%;border-radius:6px;background:linear-gradient(90deg,#8CC63F,#2E7D51)}
.bar.r i{background:linear-gradient(90deg,#E0A19A,#B0392F)}
.bar.y i{background:linear-gradient(90deg,#E8C87E,#B7791F)}

.split{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(330px,1fr))}
.split3{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(250px,1fr))}
.mini{border:1px solid var(--line);border-radius:10px;background:#fff;padding:12px 13px}
.mini h4{margin:0 0 9px 0;font-size:14.5px;color:var(--deep);display:flex;justify-content:space-between;align-items:center}
.mini h4 em{font-style:normal;font-size:11px;color:var(--muted);letter-spacing:1px;text-transform:uppercase}
.lst{list-style:none;margin:0;padding:0}
.lst li{display:flex;gap:10px;align-items:center;padding:6px 0;border-bottom:1px dashed var(--line2);font-size:13px}
.lst li:last-child{border-bottom:0}
.lst li .rk{width:21px;height:21px;flex:0 0 21px;border-radius:6px;background:var(--leaf-soft);color:var(--forest);
  font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center}
.lst li .rk.g1{background:#F6E7BE;color:#7C5E1E}
.lst li .gr{flex:1;min-width:0}
.lst li .gr b{display:block;font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.lst li .gr s{text-decoration:none;font-size:11.5px;color:var(--muted)}
.lst li .vv{font-weight:700;color:var(--deep);font-size:13px;white-space:nowrap}
.heat{display:flex;flex-wrap:wrap;gap:8px}
.hc{border:1px solid var(--line);border-radius:10px;padding:9px 11px;min-width:132px;cursor:pointer;background:#fff;flex:1}
.hc:hover{border-color:var(--mid);box-shadow:0 4px 12px rgba(30,86,49,.1)}
.hc .hn{font-size:12.5px;font-weight:700;color:var(--deep);display:flex;justify-content:space-between;gap:6px}
.hc .hv{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:18px;font-weight:700;margin:3px 0}
.hc .hs{font-size:11px;color:var(--muted)}
.hc.ok{background:linear-gradient(180deg,#F3FAF0,#fff)}
.alert-row{display:flex;gap:10px;align-items:flex-start;padding:9px 11px;border-radius:9px;margin-bottom:7px;
  border:1px solid var(--line);background:#fff;cursor:pointer}
.alert-row:hover{border-color:var(--mid)}
.alert-row .ai{width:28px;height:28px;flex:0 0 28px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:14px}
.alert-row .at{flex:1}
.alert-row .at b{display:block;font-size:13.5px}
.alert-row .at s{text-decoration:none;font-size:12px;color:var(--muted)}
.note-s{font-size:12px;color:var(--muted);margin:8px 2px 0 2px;line-height:1.5}
.empty{padding:26px;text-align:center;font-size:14px;color:var(--muted)}

.mask{position:fixed;inset:0;background:rgba(11,35,25,.5);backdrop-filter:blur(3px);z-index:200;display:none;
  align-items:flex-start;justify-content:center;padding:36px 18px}
.mask.on{display:flex}
.modal{background:#fff;border-radius:14px;width:min(1180px,100%);max-height:calc(100vh - 72px);display:flex;flex-direction:column;
  box-shadow:0 24px 60px rgba(9,30,20,.35);border:1px solid var(--line);overflow:hidden}
.modal header{display:flex;align-items:center;gap:12px;padding:13px 16px;border-bottom:1px solid var(--line);
  background:linear-gradient(180deg,#12402F,#0E3626)}
.modal header h3{margin:0;font-size:18px;color:#fff;flex:1}
.modal header .x{width:30px;height:30px;border-radius:8px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.08);
  color:#fff;cursor:pointer;font-size:15px}
.modal .mbody{padding:15px 16px;overflow:auto}
.mstat{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));margin-bottom:13px}
.mstat div{border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#FBFDFA}
.mstat div .l{font-size:10.5px;letter-spacing:1px;text-transform:uppercase;color:var(--muted);font-weight:700}
.mstat div .v{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:19px;font-weight:700;color:var(--deep)}

.toast{position:fixed;top:78px;right:18px;z-index:300;background:#fff;border:1px solid var(--line);border-left:4px solid var(--gold);
  border-radius:11px;padding:11px 14px;box-shadow:0 12px 30px rgba(15,61,46,.18);max-width:330px;transform:translateY(-16px);
  opacity:0;transition:.28s;pointer-events:none}
.toast.on{transform:translateY(0);opacity:1}
.toast b{display:block;font-size:13.5px;color:var(--deep)}
.toast s{text-decoration:none;font-size:12px;color:var(--muted)}

.tog-row{display:flex;align-items:center;gap:11px;padding:8px 10px;border:1px solid var(--line);border-radius:9px;margin-bottom:6px;background:#fff}
.tog-row .tn{flex:1;font-size:13.5px}
.tog-row .tn s{display:block;text-decoration:none;font-size:11.5px;color:var(--muted)}
.swx{width:38px;height:20px;border-radius:20px;background:#D8E2DA;position:relative;cursor:pointer;flex:0 0 38px}
.swx:after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#fff;transition:.18s;box-shadow:0 1px 3px rgba(0,0,0,.2)}
.swx.on{background:var(--mid)}.swx.on:after{left:20px}
.launch{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
.lcard{border:1px solid var(--line);border-radius:12px;background:linear-gradient(180deg,#fff,#F8FBF6);padding:14px;cursor:pointer;position:relative}
.lcard:hover{border-color:var(--mid);box-shadow:0 8px 22px rgba(30,86,49,.12);transform:translateY(-2px);transition:.16s}
.lcard .li{width:38px;height:38px;border-radius:10px;background:var(--leaf-soft);display:flex;align-items:center;justify-content:center;font-size:19px;margin-bottom:9px}
.lcard h4{margin:0 0 4px 0;font-size:15.5px;color:var(--deep)}
.lcard p{margin:0;font-size:12.5px;color:var(--muted);line-height:1.5}
.lcard .go{position:absolute;right:13px;top:13px;font-size:12px;color:var(--mid);font-weight:700}
svg .axl{font-size:10px;fill:#6E8378;font-family:"Segoe UI",sans-serif}
svg .gl{stroke:#EDF3EA;stroke-width:1}
@media print{
  .sidebar,.topbar,.filterwrap,.acts,.reopen{display:none!important}
  .main{padding:0}.sec{break-inside:avoid;box-shadow:none}
  body{background:#fff}
}
/* Target & Realisation modal (BCC style) */
.tgt-need{border-radius:12px;padding:14px 16px;margin-bottom:12px;border-left:4px solid}
.tgt-need.ok{background:var(--posbg);border-color:var(--pos)}
.tgt-need.warn{background:var(--alertbg);border-color:var(--alert)}
.tgt-need .l{font-size:12.5px;color:var(--ink2)}
.tgt-need .v{font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:30px;font-weight:700;color:var(--alert);line-height:1.1}
.tgt-need.ok .v{color:var(--pos)}
.tgt-need .v span{font-size:14px;color:var(--muted);font-weight:400}
.tgt-need .s{font-size:12.5px;color:var(--muted);margin-top:2px}
.tgt-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:9px}
.tgt-cell{border:1px solid var(--line);border-radius:9px;padding:9px 11px;background:#fff}
.tgt-cell span{display:block;font-size:11px;letter-spacing:.6px;text-transform:uppercase;color:var(--muted);font-weight:700}
.tgt-cell b{font-size:15px;color:var(--deep)}
.tgt-cell b.r{color:var(--alert)}
.tgt-strip{display:flex;gap:3px;align-items:flex-end;height:120px;padding:8px 2px;overflow-x:auto}
.tgt-bar{flex:1;min-width:16px;display:flex;flex-direction:column;align-items:center;gap:3px}
.tgt-bar-wrap{position:relative;width:100%;height:100px;background:#F0F4EF;border-radius:4px;display:flex;align-items:flex-end}
.tgt-bar-wrap i{display:block;width:100%;border-radius:4px}
.tgt-bar-wrap i.ok{background:linear-gradient(180deg,#4CAF50,#2E7D32)}
.tgt-bar-wrap i.no{background:linear-gradient(180deg,#E57373,#C62828)}
.tgt-bar-wrap u{position:absolute;left:0;right:0;border-top:2px dashed #6E8378}
.tgt-bar span{font-size:9.5px;color:var(--muted)}
.tgt-legend{display:flex;gap:14px;margin-top:8px;font-size:12px;color:var(--ink2)}
.tgt-legend .sw{display:inline-block;width:11px;height:11px;border-radius:3px;margin-right:5px;vertical-align:middle}
.tgt-legend .sw.ok{background:#2E7D32}.tgt-legend .sw.no{background:#C62828}
.tgt-legend .sw.line{border-top:2px dashed #6E8378;height:0;border-radius:0}
tr.tgt-hit td:first-child{box-shadow:inset 3px 0 0 #2E7D32}
tr.tgt-miss td:first-child{box-shadow:inset 3px 0 0 #C62828}

/* ============================================================
   RESPONSIVE — tablet (<=1024px) and mobile (<=640px)
   ============================================================ */
.mob-toggle{display:none;width:38px;height:38px;flex:0 0 38px;border-radius:9px;border:1px solid rgba(255,255,255,.2);
  background:rgba(255,255,255,.1);color:#fff;font-size:18px;cursor:pointer;align-items:center;justify-content:center}
.sb-scrim{display:none;position:fixed;inset:0;background:rgba(11,35,25,.5);z-index:65}
.sb-scrim.on{display:block}

/* ---- TABLET ---- */
@media (max-width:1024px){
  .tb-in{gap:10px;padding:8px 12px}
  .brandtxt .cn{font-size:16px}
  .brandtxt .cs{font-size:10px;letter-spacing:1.4px}
  .pulse .pi{padding:2px 10px}
  .pulse .pv{font-size:13px}
  .main{padding:14px 12px 40px 12px}
  .kgrid{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}
  .phead h1{font-size:22px}
}

/* ---- MOBILE + small tablet: drawer sidebar ---- */
@media (max-width:860px){
  .mob-toggle{display:flex}
  .shell{display:block}
  .sidebar{position:fixed;top:0;left:0;height:100vh;z-index:70;width:260px;flex-basis:260px;
    transform:translateX(-100%);transition:transform .25s ease;box-shadow:4px 0 22px rgba(0,0,0,.3)}
  .sidebar.open{transform:translateX(0)}
  .sidebar.mini{width:260px;flex-basis:260px}          /* never mini on mobile */
  .sidebar.mini .tx,.sidebar.mini .st,.sidebar.mini .bdg,.sidebar.mini .grp{display:block}
  .sidebar.mini .mi{justify-content:flex-start;padding:8px 12px;margin:1px 8px}
  .sidebar.mini .sb-search{display:block}
  .sidebar.mini .sb-foot span.t{display:inline}
  .sb-toggle{display:none}                              /* use close-on-tap instead */
  .sb-close{display:flex !important}
  .main{padding:12px 10px 48px 10px}
  .reopen,.filterwrap.hidden+.reopen{position:static}
}

/* ---- MOBILE ---- */
@media (max-width:640px){
  :root{--radius:10px}
  .tb-in{gap:8px;padding:8px 10px}
  .brandmark{width:36px;height:36px}
  .brandmark span{font-size:16px}
  .brandtxt .cn{font-size:13px;line-height:1.1}
  .brandtxt .cs{display:none}
  .pulse{display:none}                                  /* pulse strip hidden on phone */
  .who .wn,.who .wr{display:none}
  .who{padding-left:8px}
  .who img{width:32px;height:32px}
  .tb-ico{display:none}

  .frow{padding:8px 10px 0 10px;gap:8px}
  .frow.two{padding:8px 10px 10px 10px}
  .fld{flex:1 1 44%}
  .fld select,.fld input{min-width:0;width:100%}
  .frow.two .btn{flex:1 1 auto}
  .chipline{padding:0 10px 8px 10px}

  .kgrid{grid-template-columns:1fr 1fr;gap:8px}
  .kpi{padding:10px 11px}
  .kpi .kv{font-size:20px}
  .kpi .kl{font-size:10px}
  .split,.split3{grid-template-columns:1fr}
  .phead{flex-direction:column;align-items:flex-start;gap:8px}
  .phead h1{font-size:20px}
  .phead .acts{flex-wrap:wrap}
  .heat .hc{min-width:calc(50% - 8px);flex:1 1 calc(50% - 8px)}

  /* tables scroll sideways, never squash */
  .tw{-webkit-overflow-scrolling:touch}
  table.dt{font-size:12px;min-width:520px}
  table.dt th,table.dt td{padding:6px 8px}
  /* rebooking + testing tabs on phone */
  .rbk .filters{padding:8px 10px;gap:6px}
  .rbk .filters input[type="date"]{flex:1 1 40%}
  .rbk .apply-btn,.rbk .quick-btn{flex:1 1 auto}
  .rbk .sd-table{min-width:640px}
  .rbk .sec-main{font-size:13px}

  .sec>header h3{font-size:15px}
  .sec>header .sn{font-size:11px}
  .sec .body{padding:11px 10px}

  /* modal full-screen on phone */
  .mask{padding:0}
  .modal{width:100%;max-height:100vh;height:100vh;border-radius:0}
  .mstat{grid-template-columns:1fr 1fr}
  .modal .mbody{padding:12px 11px}

  .tgt-need .v{font-size:24px}
  .tgt-grid{grid-template-columns:1fr 1fr}
  .launch{grid-template-columns:1fr}

  .toast{left:10px;right:10px;max-width:none}
}
@media (max-width:400px){
  .kgrid{grid-template-columns:1fr}
  .fld{flex:1 1 100%}
  .mstat{grid-template-columns:1fr}
}
.rbk .sd-wrapper { width: 100%; font-family: Arial, Helvetica, sans-serif; background: #fff; box-sizing: border-box; padding: 4px; }
.rbk .filters { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 10px 14px; background: #f9fbe7; border: 0.5px solid #ccc; border-radius: 8px; margin-bottom: 14px; }
.rbk .filters label { font-size: 12px; color: #555; }
.rbk .filters input[type="date"] { height: 30px; padding: 0 8px; font-size: 12px; border: 0.5px solid #b0bec5; border-radius: 6px; background: #fff; }
.rbk .apply-btn, .rbk .quick-btn { height: 30px; padding: 0 14px; font-size: 12px; border: 0.5px solid #b0bec5; border-radius: 6px; background: #fff; cursor: pointer; color: #333; }
.rbk .apply-btn { background: #ed7d31; color: #fff; border-color: #ed7d31; }
.rbk .quick-btn:hover { background: #ffe0b2; }
.rbk .quick-btn.active { background: #ed7d31; color: #fff; border-color: #ed7d31; }
.rbk .section { border: 0.5px solid #ccc; border-radius: 10px; overflow: hidden; margin-bottom: 16px; }
.rbk .sec-header { display: flex; align-items: stretch; background: #ed7d31; padding: 10px 16px; }
.rbk .sec-main { font-size: 14px; font-weight: bold; color: #fff; }
.rbk .sec-sub { font-size: 11px; color: rgba(255,255,255,0.85); margin-top: 3px; }
.rbk .tbl-wrap { overflow-x: auto; }
.rbk .sd-table { width: 100%; border-collapse: collapse; font-size: 12px; min-width: 750px; }
.rbk .sd-table th { background: #37474f; color: #fff; padding: 8px 10px; text-align: center; border: 0.5px solid #4a5568; font-weight: bold; white-space: nowrap; }
.rbk .sd-table th:first-child { text-align: left; }
.rbk .sd-table td { padding: 7px 10px; text-align: center; border: 0.5px solid #ddd; background: #fff; white-space: nowrap; color: #222; }
.rbk .sd-table td:first-child { text-align: left; font-weight: bold; }
.rbk .sd-table tr:hover td { background: #fff8f0; }
.rbk .pct-new { color: #1565c0; font-weight: bold; }
.rbk .pct-existing { color: #6a1b9a; font-weight: bold; }
.rbk .ach-pct { color: #2e7d32; font-weight: bold; }
.rbk .total-row td { background: #ed7d31 !important; color: #fff !important; font-weight: bold; }
.rbk .total-row:hover td { background: #ed7d31 !important; }
.rbk .sd-note { font-size: 11px; color: #888; padding: 4px 2px; }

/* ============================================================
   FINAL MD DASHBOARD LAYOUT
   Filters stay in normal document flow above the shell.
   Sidebar starts directly below the filters.
   Main content remains fully visible.
   ============================================================ */

:root{
    --md-topbar-height:62px;
    --sbw:264px;
}

/* ERPNext cleanup */
.navbar{
    display:none !important;
}

.web-footer{
    display:none !important;
}

/* ---------- FILTER PANEL ---------- */

.filterwrap{
    position:relative !important;
    top:auto !important;
    left:auto !important;
    right:auto !important;

    width:100% !important;
    margin:0 !important;

    z-index:20;

    background:rgba(255,255,255,.97);
    backdrop-filter:blur(8px);

    border-bottom:1px solid var(--line);
    box-shadow:0 2px 10px rgba(15,61,46,.05);
}

.filterwrap.hidden{
    display:none !important;
}

/* First filter row */
.filterwrap .frow:not(.two){
    display:grid !important;

    grid-template-columns:
        minmax(190px,1fr)
        minmax(190px,1fr)
        minmax(190px,1fr)
        minmax(190px,1fr)
        minmax(190px,1fr);

    gap:16px;
    align-items:end;

    width:100%;
    padding:16px 24px 0 24px !important;
    box-sizing:border-box;
}

.filterwrap .frow:not(.two) .fld{
    width:100%;
    min-width:0 !important;
}

.filterwrap .fld select,
.filterwrap .fld input{
    width:100% !important;
    min-width:0 !important;
}

/* Filter button row */
.filterwrap .frow.two{
    display:flex !important;
    align-items:center;
    gap:12px;
    flex-wrap:wrap;

    width:100%;
    padding:10px 24px 8px 24px !important;
    box-sizing:border-box;
}

.filterwrap .frow.two .btn{
    flex:0 0 auto;
}

.filterwrap .frow.two .btn:last-child{
    margin-left:auto !important;
}

/* Filter chips */
.filterwrap .chipline{
    display:flex;
    align-items:center;
    gap:8px;
    flex-wrap:wrap;

    width:100%;
    padding:0 24px 11px 24px !important;
    box-sizing:border-box;
}

/* ---------- REOPEN FILTER BUTTON ---------- */

.reopen{
    display:none;
}

.reopen.on{
    display:flex;
    justify-content:center;

    width:100%;
    position:relative !important;

    top:auto !important;
    left:auto !important;

    transform:none !important;

    z-index:25;
    pointer-events:none;
}

.reopen button{
    pointer-events:auto;

    width:126px;
    height:25px;

    padding:0 16px;

    border:1px solid var(--line);
    border-top:0;

    border-radius:0 0 12px 12px;

    background:#fff;
    color:var(--forest);

    box-shadow:0 3px 12px rgba(15,61,46,.10);

    font-size:12px;
    cursor:pointer;
}

/* ---------- MAIN SHELL ---------- */

.shell{
    display:flex !important;
    align-items:flex-start;
    gap:0;

    width:100%;
    position:relative;
}

/* ---------- SIDEBAR ---------- */

.sidebar{
    width:var(--sbw) !important;
    flex:0 0 var(--sbw) !important;

    position:sticky !important;
    top:var(--md-topbar-height) !important;

    height:calc(100vh - var(--md-topbar-height)) !important;

    z-index:30;

    overflow:hidden;

    background:linear-gradient(
        180deg,
        #12402F 0%,
        #0D3324 100%
    ) !important;

    border-right:1px solid #0A2A1D !important;

    color:#E7F2E8 !important;
    opacity:1 !important;
    filter:none !important;

    transition:
        width .22s ease,
        flex-basis .22s ease;
}

.sidebar.mini{
    width:60px !important;
    flex:0 0 60px !important;
}

.sidebar .sb-top,
.sidebar .sb-nav,
.sidebar .sb-scroll,
.sidebar .sb-bottom{
    background:transparent !important;
    opacity:1 !important;
}

.sidebar .mi,
.sidebar .mi span,
.sidebar .grp{
    opacity:1 !important;
}

/* ---------- MAIN CONTENT ---------- */

.main{
    flex:1;
    min-width:0;

    width:auto !important;
    margin:0 !important;

    padding:16px 24px 40px 24px !important;

    box-sizing:border-box;
}

body.filters-expanded .main,
body.filters-collapsed .main{
    padding-top:16px !important;
}

body.filters-expanded .sidebar,
body.filters-collapsed .sidebar{
    top:var(--md-topbar-height) !important;
    height:calc(100vh - var(--md-topbar-height)) !important;
}

/* ---------- SIDEBAR TOGGLE ---------- */

.sb-toggle{
    width:30px;
    height:30px;

    flex:0 0 30px;

    display:flex;
    align-items:center;
    justify-content:center;

    border-radius:7px;

    border:1px solid rgba(255,255,255,.16);
    background:rgba(255,255,255,.08);

    color:#CFE8D2;

    cursor:pointer;

    font-size:14px;
    line-height:1;

    transition:
        background .18s ease,
        color .18s ease;
}

.sb-toggle:hover{
    background:rgba(255,255,255,.16);
}

.sidebar.mini .sb-toggle{
    color:#F2C64C;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width:1200px){

    .filterwrap .frow:not(.two){
        grid-template-columns:repeat(3,minmax(180px,1fr));
    }
}

@media (max-width:860px){

    .filterwrap .frow:not(.two){
        grid-template-columns:repeat(2,minmax(0,1fr));
        gap:10px;

        padding-left:12px !important;
        padding-right:12px !important;
    }

    .filterwrap .frow.two{
        padding-left:12px !important;
        padding-right:12px !important;
    }

    .filterwrap .frow.two .btn:last-child{
        margin-left:0 !important;
    }

    .filterwrap .chipline{
        padding-left:12px !important;
        padding-right:12px !important;
    }

    .shell{
        display:block !important;
    }

    .sidebar{
        position:fixed !important;

        top:0 !important;
        left:0;

        width:260px !important;
        flex:0 0 260px !important;

        height:100vh !important;

        z-index:80;

        transform:translateX(-100%);
        transition:transform .25s ease;
    }

    .sidebar.open{
        transform:translateX(0);
    }

    .sidebar.mini{
        width:260px !important;
        flex:0 0 260px !important;
    }

    .main{
        width:100% !important;

        padding:
            12px
            12px
            40px
            12px !important;
    }

    .sb-toggle{
        display:none;
    }

    .sb-close{
        display:flex !important;
    }
}

@media (max-width:640px){

    .filterwrap .frow:not(.two){
        grid-template-columns:1fr;
    }

    body.filters-collapsed .main{
        padding-top:12px !important;
    }
}


/* ============================================================
   WHEN FILTERS ARE COLLAPSED
   SIDEBAR USES THE FREED SPACE ABOVE
   ============================================================ */

body.filters-collapsed .sidebar{
    position:sticky !important;

    top:var(--md-topbar-height) !important;

    height:calc(
        100vh - var(--md-topbar-height)
    ) !important;
}


/* Remove the empty filter gap from the shell */

body.filters-collapsed .shell{
    margin-top:0 !important;
}


/* Main content also starts immediately */

body.filters-collapsed .main{
    padding-top:16px !important;
}

/* ============================================================
   SIDEBAR — LIGHT BACKGROUND ONLY
   All existing sidebar text/icon/active colors are preserved.
   ============================================================ */

.sidebar{
    background:linear-gradient(
        180deg,
        #E3EFE3 0%,
        #D7E7D8 100%
    ) !important;
}

/* ============================================================
   FINAL MD SIDEBAR REFINEMENTS
   Light background + readable existing navigation
   + compact icon-only mini sidebar
   ============================================================ */

.sidebar{
    background:linear-gradient(
        180deg,
        #DCEADC 0%,
        #D3E4D4 100%
    ) !important;

    border-right:1px solid #BFD1C0 !important;
}

/* Keep sidebar text readable on the light background */
.sidebar{
    color:#274A38 !important;
}

.sidebar .grp{
    color:#547562 !important;
    opacity:1 !important;
}

.sidebar .mi,
.sidebar .mi .tx{
    color:#28513D !important;
}

.sidebar .mi:hover{
    color:#173C2A !important;
}

.sidebar .mi.on,
.sidebar .mi.on .tx{
    color:#173C2A !important;
}

.sidebar .sb-search{
    color:#274A38 !important;
}

.sidebar .sb-search::placeholder{
    color:#718B78 !important;
}

.sidebar .sb-foot{
    color:#5E7E69 !important;
}

/* Favourite stars remain clearly visible */
.sidebar .mi .st.fav{
    color:#D59A17 !important;
    opacity:1 !important;
}

/* Mini sidebar: remove horizontal padding/margins around icons */
.sidebar.mini .mi{
    width:100% !important;

    padding-left:0 !important;
    padding-right:0 !important;

    margin-left:0 !important;
    margin-right:0 !important;

    gap:0 !important;

    justify-content:center !important;

    background:transparent !important;
    box-shadow:none !important;
}

.sidebar.mini .mi .ic{
    width:30px !important;
    height:30px !important;
    flex:0 0 30px !important;

    margin:0 !important;

    display:flex !important;
    align-items:center !important;
    justify-content:center !important;

    box-shadow:none !important;
}

/* No stretched active shadow when mini */
.sidebar.mini .mi.on{
    background:transparent !important;
    box-shadow:none !important;
}

.sidebar.mini .mi.on .ic{
    box-shadow:none !important;
}

/* ============================================================
   COLLAPSED FILTERS — NO EMPTY TOP ROW
   ============================================================ */

body.filters-collapsed .reopen,
body.filters-collapsed .reopen.on{
    position:fixed !important;

    top:var(--md-topbar-height) !important;

    left:calc(
        var(--sbw) +
        (100vw - var(--sbw)) / 2
    ) !important;

    width:auto !important;
    height:auto !important;

    margin:0 !important;

    transform:translateX(-50%) !important;

    display:flex !important;
    justify-content:center !important;

    z-index:75 !important;

    pointer-events:none !important;
}

body.filters-collapsed .reopen button{
    pointer-events:auto !important;
}

body.filters-collapsed .shell{
    margin-top:0 !important;
    padding-top:0 !important;
}

/* ============================================================
   MD DASHBOARD — RIGHT EDGE PANELS
   Fully namespaced. Does not alter .sidebar, .main, .filterwrap,
   .btn, tables, cards, or existing dashboard layout.
   ============================================================ */

#md-edge-root{
    position:relative;
    z-index:0;
}

/* ---------- EDGE TABS ---------- */

.md-edge-tab{
    position:fixed !important;
    right:0 !important;

    width:46px !important;
    height:116px !important;

    padding:10px 6px !important;

    display:flex !important;
    flex-direction:column !important;
    align-items:center !important;
    justify-content:space-between !important;
    gap:7px !important;

    border:0 !important;
    border-radius:12px 0 0 12px !important;

    color:#fff !important;

    writing-mode:vertical-rl !important;
    text-orientation:mixed !important;

    white-space:nowrap !important;

    font-family:Inter,"Segoe UI",Arial,sans-serif !important;
    font-size:10px !important;
    font-weight:800 !important;
    line-height:1.15 !important;
    letter-spacing:1.2px !important;

    cursor:pointer !important;

    z-index:340 !important;

    box-shadow:-3px 3px 16px rgba(15,61,46,.22) !important;

    transition:
        transform .18s ease,
        filter .18s ease !important;
}

.md-edge-tab:hover{
    transform:translateX(-3px);
    filter:brightness(1.05);
}

.md-edge-tab-appt{
    top:calc(50vh - 120px) !important;
    background:linear-gradient(135deg,#1B5E20,#2E7D51) !important;
}

.md-edge-tab-floor{
    top:calc(50vh + 2px) !important;
    background:linear-gradient(135deg,#14501F,#43A047) !important;
}

.md-edge-count{
    writing-mode:horizontal-tb !important;

    min-width:24px;
    height:24px;

    display:inline-flex;
    align-items:center;
    justify-content:center;

    padding:0 5px;

    border-radius:999px;

    background:#fff;

    font-size:10px;
    font-weight:800;
    letter-spacing:0;
}

.md-edge-tab-appt .md-edge-count{
    color:#1B5E20;
}

.md-edge-tab-floor .md-edge-count{
    color:#14501F;
}


/* ---------- PANELS ---------- */

.md-edge-panel{
    position:fixed !important;

    top:16px !important;
    right:-480px !important;

    width:420px !important;
    max-width:calc(100vw - 32px) !important;

    height:calc(100vh - 32px) !important;

    display:flex !important;
    flex-direction:column !important;

    overflow:hidden !important;

    border:1px solid rgba(255,255,255,.90) !important;
    border-radius:18px !important;

