/* ============================================================
   MD DASHBOARD — EMBEDDED / SUBPAGE EDGE PANEL OPTIMISATION
   Activated only when the MD Dashboard is running inside the
   LIFE Portal iframe. Standalone /md-dashboard remains unchanged.
   ============================================================ */

html.md-dashboard-embedded{
    --md-embedded-top-safe:72px;
    --md-embedded-bottom-safe:14px;
}


/* Keep edge tabs comfortably below the MD header/filter region */
html.md-dashboard-embedded .md-edge-tab-appt{
    top:calc(50vh - 42px) !important;
}

html.md-dashboard-embedded .md-edge-tab-floor{
    top:calc(50vh + 80px) !important;
}


