html.md-dashboard-embedded .md-edge-panel{
    top:var(--md-embedded-top-safe) !important;

    right:-430px !important;

    width:360px !important;
    max-width:calc(100vw - 110px) !important;

    height:calc(
        100vh -
        var(--md-embedded-top-safe) -
        var(--md-embedded-bottom-safe)
    ) !important;

    min-height:0 !important;

    border-radius:14px !important;

    box-shadow:
