@media (max-width:1350px){

    html.md-dashboard-embedded .filterwrap{
        grid-template-columns:1fr !important;

        grid-template-areas:
            "filters"
            "actions"
            "chips" !important;
    }

    html.md-dashboard-embedded .filterwrap .frow:not(.two){
        grid-template-columns:
            repeat(6,minmax(0,1fr))
        !important;
    }

    html.md-dashboard-embedded .filterwrap .frow.two{
        justify-content:start !important;

        padding-top:8px !important;
    }

    html.md-dashboard-embedded .filterwrap .chipline{
        padding-top:7px !important;
    }
}


/* ------------------------------------------------------------
   TABLET / SMALL DESKTOP
   ------------------------------------------------------------ */

@media (max-width:1200px){

    html:not(.md-dashboard-embedded) .filterwrap{
        display:block !important;

        padding:10px 14px 8px !important;
    }

    html:not(.md-dashboard-embedded) .filterwrap .frow:not(.two){
        display:grid !important;

        grid-template-columns:
            repeat(3,minmax(0,1fr))
        !important;

        gap:10px !important;

        padding:0 !important;
    }

    html:not(.md-dashboard-embedded) .filterwrap .frow.two{
        display:flex !important;
        flex-wrap:wrap !important;

        gap:7px !important;

        padding:8px 0 0 !important;
    }

    html:not(.md-dashboard-embedded) .filterwrap .chipline{
        padding:7px 0 0 !important;
    }
}


/* ------------------------------------------------------------
   MOBILE
   ------------------------------------------------------------ */

@media (max-width:760px){

    html.md-dashboard-embedded .filterwrap,
    html:not(.md-dashboard-embedded) .filterwrap{
        display:block !important;

        padding:9px 10px 8px !important;
    }

    html.md-dashboard-embedded .filterwrap .frow:not(.two),
    html:not(.md-dashboard-embedded) .filterwrap .frow:not(.two){
        display:grid !important;

        grid-template-columns:1fr 1fr !important;

        gap:8px !important;

        padding:0 !important;
    }

    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld,
    html:not(.md-dashboard-embedded) .filterwrap .frow:not(.two) .fld{
        grid-column:auto !important;
    }

    html.md-dashboard-embedded .filterwrap .frow.two,
    html:not(.md-dashboard-embedded) .filterwrap .frow.two{
        display:flex !important;
        flex-wrap:wrap !important;

        gap:6px !important;

        padding:8px 0 0 !important;
    }

    html.md-dashboard-embedded .filterwrap .chipline,
    html:not(.md-dashboard-embedded) .filterwrap .chipline{
        padding:7px 0 0 !important;
    }
}

@media (max-width:520px){

    html.md-dashboard-embedded .filterwrap .frow:not(.two),
    html:not(.md-dashboard-embedded) .filterwrap .frow:not(.two){
        grid-template-columns:1fr !important;
    }
}

/* ============================================================
   FINAL FILTER COLLAPSE / REOPEN FIX
   IMPORTANT: keep this block at the absolute end of the CSS.
   The responsive grid rules above use display:grid !important,
   so the hidden state must override them with higher specificity.
   ============================================================ */

/* Expanded state: reopen control must NEVER be visible */
html body:not(.filters-collapsed) #reopen,
html body.filters-expanded #reopen,
html body.filters-expanded #reopen.on{
    display:none !important;
}


/* Hidden filter panel must override every standalone/embedded grid rule */
html body #filterwrap.hidden,
html.md-dashboard-embedded body #filterwrap.hidden,
html:not(.md-dashboard-embedded) body #filterwrap.hidden{
    display:none !important;

    visibility:hidden !important;

    height:0 !important;
    min-height:0 !important;
    max-height:0 !important;

    margin:0 !important;
    padding:0 !important;

    border:0 !important;
    box-shadow:none !important;

    overflow:hidden !important;
}


/* Collapsed state: show only the small reopen tab */
html body.filters-collapsed #reopen.on{
    display:flex !important;

    position:fixed !important;

    top:var(--md-topbar-height) !important;

    left:calc(
        var(--sbw) +
        (100vw - var(--sbw)) / 2
    ) !important;

    width:auto !important;
    height:auto !important;

    margin:0 !important;
    padding:0 !important;

    transform:translateX(-50%) !important;

    justify-content:center !important;
    align-items:flex-start !important;

    z-index:90 !important;

    pointer-events:none !important;
}


/* Reopen button itself */
html body.filters-collapsed #reopen.on button{
    width:126px !important;
    height:25px !important;

    padding:0 14px !important;
    margin:0 !important;

    display:flex !important;
    align-items:center !important;
    justify-content:center !important;

    pointer-events:auto !important;

    border:1px solid var(--line) !important;
    border-top:0 !important;

    border-radius:0 0 11px 11px !important;

    background:rgba(255,255,255,.98) !important;

    color:var(--forest) !important;

    box-shadow:0 4px 12px rgba(15,61,46,.10) !important;

    font-size:11px !important;
    line-height:1 !important;

    cursor:pointer !important;
}


/* When filters close, shell moves up immediately */
html body.filters-collapsed .shell{
    margin-top:0 !important;
    padding-top:0 !important;
}


/* Embedded iframe: centre reopen button in the MD dashboard viewport.
   Do not account for the parent LIFE Portal sidebar because it is
   outside this iframe. */
html.md-dashboard-embedded body.filters-collapsed #reopen.on{
    left:50% !important;
}


/* Mobile */
@media(max-width:860px){

    html body.filters-collapsed #reopen.on,
    html.md-dashboard-embedded body.filters-collapsed #reopen.on{
        left:50% !important;
    }
}

/* ============================================================
   FINAL SUBPAGE FILTER DESIGN
   Optimized ONLY for MD Dashboard inside LIFE Portal iframe.
   Standalone page is intentionally not targeted here.
   Keep this block at the absolute end of the CSS.
   ============================================================ */

/* ---------- WRAPPER ---------- */

html.md-dashboard-embedded .filterwrap{
    display:grid !important;

    grid-template-columns:1fr !important;
    grid-template-areas:
        "fields"
        "bottom" !important;

    width:100% !important;

    padding:10px 14px 9px 14px !important;

    margin:0 !important;

    box-sizing:border-box !important;

    row-gap:8px !important;
}


/* ============================================================
   ROW 1 — ALL 5 FILTERS IN ONE LINE
   Period gets slightly more width.
   ============================================================ */

html.md-dashboard-embedded .filterwrap .frow:not(.two){
    grid-area:fields !important;

    display:grid !important;

    grid-template-columns:
        minmax(0,1.25fr)
        minmax(0,1fr)
        minmax(0,1fr)
        minmax(0,1fr)
        minmax(0,1fr)
    !important;

    gap:10px !important;

    width:100% !important;

    padding:0 !important;
    margin:0 !important;

    align-items:end !important;

    box-sizing:border-box !important;
}

html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld{
    grid-column:auto !important;

    width:100% !important;

    min-width:0 !important;
    max-width:none !important;

    padding:0 !important;
    margin:0 !important;
}


/* ---------- LABELS ---------- */

html.md-dashboard-embedded .filterwrap .fld label{
    display:block !important;

    margin:0 0 4px 1px !important;
    padding:0 !important;

    min-height:0 !important;

    font-size:9.5px !important;
    line-height:1.15 !important;

    letter-spacing:.55px !important;

    white-space:nowrap !important;
}


/* ---------- INPUTS ---------- */

html.md-dashboard-embedded .filterwrap .fld input,
html.md-dashboard-embedded .filterwrap .fld select{
    display:block !important;

    width:100% !important;

    min-width:0 !important;
    max-width:none !important;

    height:36px !important;
    min-height:36px !important;
    max-height:36px !important;

    margin:0 !important;

    padding:0 10px !important;

    box-sizing:border-box !important;

    font-size:11.5px !important;
    line-height:36px !important;

    border-radius:8px !important;
}


/* ============================================================
   ROW 2 — BUTTONS + STATUS CHIPS ON SAME LINE
   No artificial spacing. Everything follows naturally.
   ============================================================ */

html.md-dashboard-embedded .filterwrap{
    grid-template-columns:auto minmax(0,1fr) !important;

    grid-template-areas:
        "fields fields"
        "actions chips" !important;

    column-gap:8px !important;
}

html.md-dashboard-embedded .filterwrap .frow.two{
    grid-area:actions !important;

    display:flex !important;

    align-items:center !important;
    justify-content:flex-start !important;

    flex-wrap:nowrap !important;

    gap:6px !important;

    width:auto !important;

    padding:0 !important;
    margin:0 !important;

    box-sizing:border-box !important;
}


/* ---------- ALL BUTTONS ---------- */

html.md-dashboard-embedded .filterwrap .frow.two .btn{
    position:static !important;

    width:auto !important;
    min-width:0 !important;
    max-width:none !important;

    height:31px !important;
    min-height:31px !important;
    max-height:31px !important;

    margin:0 !important;

    padding:0 9px !important;

    display:inline-flex !important;

    align-items:center !important;
    justify-content:center !important;

    flex:0 0 auto !important;

    transform:none !important;

    white-space:nowrap !important;

    font-size:10.5px !important;
    line-height:1 !important;

    border-radius:8px !important;
}


/* Generate button slightly wider */
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(1){
    min-width:156px !important;

    padding-left:12px !important;
    padding-right:12px !important;
}


/* Reset */
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(2){
    min-width:68px !important;
}


/* Print / Excel */
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(3),
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(4){
    min-width:64px !important;
}


/* Full */
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(5){
    min-width:60px !important;
}


/* Hide Filters */
html.md-dashboard-embedded .filterwrap .frow.two .btn:nth-child(6){
    min-width:100px !important;
}


/* ---------- CHIPS ---------- */

html.md-dashboard-embedded .filterwrap .chipline{
    grid-area:chips !important;

    display:flex !important;

    align-items:center !important;
    justify-content:flex-start !important;

    flex-wrap:nowrap !important;

    gap:5px !important;

    width:auto !important;
    min-width:0 !important;

    padding:0 !important;
    margin:0 !important;

    overflow:hidden !important;

    box-sizing:border-box !important;
}

html.md-dashboard-embedded .filterwrap .chip{
    height:25px !important;

    padding:0 8px !important;

    display:inline-flex !important;

    align-items:center !important;
    justify-content:center !important;

    flex:0 0 auto !important;

    white-space:nowrap !important;

    font-size:9.5px !important;
    line-height:1 !important;
}


/* ============================================================
   MEDIUM IFRAME
   Parent portal sidebar can reduce usable width.
   Keep 5 filters in one row as long as practical.
   ============================================================ */

@media(max-width:1180px){

    html.md-dashboard-embedded .filterwrap{
        grid-template-columns:1fr !important;

        grid-template-areas:
            "fields"
            "actions"
            "chips" !important;
    }

    html.md-dashboard-embedded .filterwrap .frow.two{
        flex-wrap:wrap !important;
    }

    html.md-dashboard-embedded .filterwrap .chipline{
        flex-wrap:wrap !important;
        overflow:visible !important;
    }
}


/* ============================================================
   NARROW EMBEDDED VIEW
   Only here do filters wrap to 3 + 2.
   ============================================================ */

@media(max-width:980px){

    html.md-dashboard-embedded .filterwrap .frow:not(.two){
        grid-template-columns:
            repeat(6,minmax(0,1fr))
        !important;
    }

    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld:nth-child(1),
    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld:nth-child(2),
    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld:nth-child(3){
        grid-column:span 2 !important;
    }

    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld:nth-child(4),
    html.md-dashboard-embedded .filterwrap .frow:not(.two) .fld:nth-child(5){
        grid-column:span 3 !important;
    }
}


/* ============================================================
   FILTER COLLAPSE MUST STILL WIN
   ============================================================ */

html.md-dashboard-embedded body #filterwrap.hidden{
    display:none !important;
}


/* ============================================================
   EMBEDDED FILTERS — SHRINK DATE FIELDS
   ============================================================ */

html.md-dashboard-embedded
.filterwrap
.frow:not(.two){

    grid-template-columns:
        minmax(210px,1.25fr)  /* Period */
        155px                 /* From */
        155px                 /* To */
        minmax(190px,1fr)     /* Cluster */
        minmax(190px,1fr)     /* Branch */
    !important;

    gap:10px !important;
}


/* Date fields themselves */
html.md-dashboard-embedded
.filterwrap
.frow:not(.two)
.fld:nth-child(2),

html.md-dashboard-embedded
.filterwrap
.frow:not(.two)
.fld:nth-child(3){

    width:155px !important;
    max-width:155px !important;
}


/* Date inputs */
html.md-dashboard-embedded
.filterwrap
input[type="date"]{

    width:155px !important;
    max-width:155px !important;

    padding-left:10px !important;
    padding-right:8px !important;
}

/* TEMPORARILY HIDE FILTER CHIPS */
#chipline{
    display:none !important;
}

/* ============================================================
   TEMPORARILY HIDE LIVE DATA BANNER
   ============================================================ */

.live-banner,
#liveBanner,
.live-status,
#liveStatus{
    display:none !important;
}


/* ============================================================
   SIDEBAR SEARCH — RESTORE CLEAR BORDER
   ============================================================ */

.sidebar .sb-search{
    background:rgba(255,255,255,.60) !important;

    border:1px solid #B7CDBA !important;

    outline:none !important;

    box-shadow:
        inset 0 0 0 1px rgba(255,255,255,.30) !important;

    color:#274A38 !important;
}


/* Search hover */
.sidebar .sb-search:hover{
    border-color:#9DBCA2 !important;

    background:rgba(255,255,255,.76) !important;
}


/* Search focus */
.sidebar .sb-search:focus{
    border-color:#6FA67A !important;

    background:#FFFFFF !important;

    box-shadow:
        0 0 0 2px rgba(74,135,84,.10) !important;
}


/* ============================================================
   SIDEBAR COLLAPSE BUTTON — RESTORE BORDER / OUTLINE
   ============================================================ */

.sidebar .sb-toggle{
    background:rgba(255,255,255,.58) !important;

    border:1px solid #AFC7B3 !important;

    outline:none !important;

    box-shadow:
        0 1px 3px rgba(42,79,55,.08) !important;

    color:#315844 !important;
}


/* Hover */
.sidebar .sb-toggle:hover{
    background:#FFFFFF !important;

    border-color:#7EA487 !important;

    box-shadow:
        0 2px 5px rgba(42,79,55,.12) !important;
}


/* Keyboard focus */
.sidebar .sb-toggle:focus-visible{
    border-color:#5F956A !important;

    box-shadow:
        0 0 0 2px rgba(75,135,84,.14) !important;
}


/* Mini sidebar collapse button */
.sidebar.mini .sb-toggle{
    background:rgba(255,255,255,.62) !important;

    border:1px solid #AFC7B3 !important;
}

/* ============================================================
   SIDEBAR — MANUAL COLLAPSE ONLY
   ============================================================ */

.sidebar.mini:hover{
    width:var(--sbw-mini,60px) !important;
    flex-basis:var(--sbw-mini,60px) !important;
}


/* Never reveal text just because sidebar is hovered */
.sidebar.mini:hover .tx,
.sidebar.mini:hover .grp,
.sidebar.mini:hover .sb-search,
.sidebar.mini:hover .sb-foot{
    display:none !important;
}


/* Sidebar changes only through .mini class */
.sidebar{
    transition:
        width .22s ease,
        flex-basis .22s ease !important;
}

/* Hide obsolete auto-minimise control */
#swAuto{
    display:none !important;
}
