/* Sidebar is manual-only: .mini changes only via toggleSidebar(). */

/* ================= FORMATTERS ================= */
/* AMTMODE: 'A' Auto · 'F' Full · 'K' thousands · 'L' Lakhs · 'C' Crore */
var AMTMODE='F';

/* one Indian-format engine — same value, five views */
function fmtIN(n){var s=Math.round(n).toLocaleString('en-IN');return s;}
function amt(v,mode){
  v=+v||0; mode=mode||AMTMODE;
  var neg=v<0?'-':''; var a=Math.abs(v);
  if(mode==='F') return neg+'₹'+fmtIN(a);
  if(mode==='K') return neg+'₹'+(a/1000).toFixed(2)+'k';
  if(mode==='L') return neg+'₹'+(a/100000).toFixed(2)+'L';
  if(mode==='C') return neg+'₹'+(a/10000000).toFixed(2)+'Cr';
  /* AUTO: pick the tier that reads cleanest */
  if(a>=10000000) return neg+'₹'+(a/10000000).toFixed(2)+'Cr';
  if(a>=100000)   return neg+'₹'+(a/100000).toFixed(2)+'L';
  if(a>=1000)     return neg+'₹'+(a/1000).toFixed(1)+'k';
  return neg+'₹'+fmtIN(a);
}
/* real net per branch: use server's live-tax b.net if present,
   else fall back to gross ÷ 1.05 (×100/105). */
function brNet(b){
  if(b && b.net && b.net>0) return b.net;
  return (b && b.gsale ? b.gsale/1.05 : 0);
}
/* company net: sum live net if we have it, else gross ÷ 1.05 */
function netAll(){
  var haveNet=false;
  for(var i=0;i<BR.length;i++){ if(BR[i].net&&BR[i].net>0){haveNet=true;break;} }
  if(haveNet) return T('net');
  return T('gsale')/1.05;
}
/* Back-compat: every existing call now flows through the toggle.
   money(), mL(), mC() are kept as names so nothing else breaks —
   but they ALL now respect AMTMODE instead of being locked. */
function money(v){return amt(v);}
function mL(v){return amt(v);}
function mC(v){return amt(v);}
function pc(v,d){return (+v||0).toFixed(d===undefined?1:d)+'%';}
function T(f){var s=0;for(var i=0;i<BR.length;i++){var b=BR[i];s+=(typeof f==='function'?f(b):(b[f]||0));}return s;}

/* ================= UI HELPERS ================= */
function sec(title,note,body,tone,closed){
  return '<section class="sec '+(tone||'')+' '+(closed?'closed':'')+'">'+
    '<header onclick="this.parentNode.classList.toggle(\'closed\')">'+
      '<span class="dot"></span><h3>'+title+'</h3><span class="sn">'+(note||'')+'</span><span class="cv">▾</span>'+
    '</header><div class="body">'+body+'</div></section>';
}
function kpi(label,val,sub,tone,trend,click){
  return '<div class="kpi '+(tone||'')+' '+(click?'clk':'')+'" '+(click?'onclick="'+click+'"':'')+'>'+
    (trend||'')+'<div class="kl">'+label+'</div><div class="kv">'+val+'</div><div class="ks">'+(sub||'')+'</div></div>';
}
function table(cols,rows,foot,cls){
  var th=cols.map(function(c,i){return '<th class="'+(c.num?'num':'')+'" data-i="'+i+'" data-t="'+(c.num?'n':'s')+'">'+c.t+'</th>';}).join('');
  var tb=rows.map(function(r){return '<tr class="'+(r.click?'clk':'')+'" '+(r.click?'onclick="'+r.click+'"':'')+'>'+
      r.c.map(function(c,i){return '<td class="'+(cols[i].num?'num':'')+'">'+c+'</td>';}).join('')+'</tr>';}).join('');
  var tf=foot?'<tfoot><tr>'+foot.map(function(f,i){return '<td class="'+(cols[i]&&cols[i].num?'num':'')+'">'+f+'</td>';}).join('')+'</tr></tfoot>':'';
  return '<div class="tw '+(cls||'')+'"><table class="dt"><thead><tr>'+th+'</tr></thead><tbody>'+tb+'</tbody>'+tf+'</table></div>';
}
function d2(a,b){return '<div class="d2"><b>'+a+'</b><s>'+(b||'')+'</s></div>'}
function barpc(v,max,tone){var w=Math.max(2,Math.min(100,(v||0)/max*100));
  return '<div class="bar '+(tone||'')+'"><i style="width:'+w+'%"></i></div>';}
function emptyBox(msg){var match=String(msg).match(/md_[a-z_]+_api/),method=match&&match[0];if(method&&mdModuleErrors&&mdModuleErrors[method])return '<div class="empty md-unavailable">This report could not load from ERP. Existing figures are not replaced with zero. <button type="button" onclick="loadModules();render()">↻ Retry reports</button></div>';return '<div class="empty">'+msg+'</div>';}

document.addEventListener('click',function(e){
  var th=e.target.closest?e.target.closest('table.dt th'):null; if(!th)return;
  var tbl=th.closest('table'),tb=tbl.tBodies[0],i=+th.dataset.i,num=th.dataset.t==='n';
  var asc=!th.classList.contains('asc');
  tbl.querySelectorAll('th').forEach(function(x){x.classList.remove('asc','desc');});
  th.classList.add(asc?'asc':'desc');
  var rows=[].slice.call(tb.rows);
  var val=function(r){var t=r.cells[i]?r.cells[i].innerText.trim():'';
    if(!num)return t.toLowerCase();
    var m=t.replace(/[^0-9.\-]/g,''); return m===''?-Infinity:parseFloat(m);};
  rows.sort(function(a,b){var x=val(a),y=val(b);if(x<y)return asc?-1:1;if(x>y)return asc?1:-1;return 0;});
  rows.forEach(function(r){tb.appendChild(r);});
});

/* ============================================================
   SYNC SIDEBAR WITH ACTUAL FILTER HEIGHT
   ============================================================ */

function syncSidebarLayout(){

    var filterwrap = document.getElementById('filterwrap');

    if(
        filterwrap &&
        filterwrap.classList.contains('hidden')
    ){
        document.body.classList.add('filters-collapsed');
        document.body.classList.remove('filters-expanded');
    }else{
        document.body.classList.remove('filters-collapsed');
        document.body.classList.add('filters-expanded');
    }
}

/* --- charts --- */
function lineChart(series,labels,opts){
  opts=opts||{}; var W=opts.w||980,H=opts.h||230,pl=52,pb=26,pt=14;
  if(!labels.length) return emptyBox('No trend data for this range.');
  var all=series.reduce(function(a,s){return a.concat(s.d);},[]);
  var max=Math.max.apply(null,all)*1.12||1, min=0;
  var sx=function(i){return pl+(W-pl-14)*(i/Math.max(1,(labels.length-1)));};
  var sy=function(v){return pt+(H-pt-pb)*(1-(v-min)/(max-min));};
  var g='';
  for(var k=0;k<=4;k++){var y=pt+(H-pt-pb)*(k/4);
    g+='<line class="gl" x1="'+pl+'" y1="'+y+'" x2="'+(W-6)+'" y2="'+y+'"/>'+
       '<text class="axl" x="'+(pl-8)+'" y="'+(y+3)+'" text-anchor="end">'+(max*(1-k/4)).toFixed(0)+'</text>';}
  series.forEach(function(s){
    var p=s.d.map(function(v,i){return (i?'L':'M')+sx(i)+','+sy(v);}).join(' ');
    if(s.fill) g+='<path d="'+p+' L'+sx(s.d.length-1)+','+(H-pb)+' L'+pl+','+(H-pb)+' Z" fill="'+s.fill+'" opacity=".28"/>';
    g+='<path d="'+p+'" fill="none" stroke="'+s.c+'" stroke-width="'+(s.w||2.4)+'" stroke-dasharray="'+(s.dash||'')+'"/>';
    s.d.forEach(function(v,i){g+='<circle cx="'+sx(i)+'" cy="'+sy(v)+'" r="3.1" fill="#fff" stroke="'+s.c+'" stroke-width="2"><title>'+labels[i]+': '+v.toFixed(1)+'</title></circle>';});
  });
  labels.forEach(function(l,i){g+='<text class="axl" x="'+sx(i)+'" y="'+(H-8)+'" text-anchor="middle">'+l+'</text>';});
  return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:'+H+'px">'+g+'</svg>';
}
function barChart(data,opts){
  opts=opts||{}; var W=opts.w||980,H=opts.h||250,pl=52,pb=26,pt=14;
  if(!data.length) return emptyBox('No data.');
  var max=Math.max.apply(null,data.map(function(d){return Math.max(d.v,d.v2||0);}))*1.12||1;
  var bw=(W-pl-10)/data.length;
  var g='';
  for(var k=0;k<=4;k++){var y=pt+(H-pt-pb)*(k/4);
    g+='<line class="gl" x1="'+pl+'" y1="'+y+'" x2="'+(W-6)+'" y2="'+y+'"/>'+
       '<text class="axl" x="'+(pl-8)+'" y="'+(y+3)+'" text-anchor="end">'+(max*(1-k/4)).toFixed(0)+'</text>';}
  data.forEach(function(d,i){
    var x=pl+i*bw, h=(d.v/max)*(H-pt-pb);
    g+='<rect x="'+(x+bw*.18)+'" y="'+(H-pb-h)+'" width="'+(bw*.64)+'" height="'+h+'" rx="3" fill="'+(d.c||'#2E7D51')+'"><title>'+d.l+': '+d.v+'</title></rect>';
    g+='<text class="axl" x="'+(x+bw/2)+'" y="'+(H-8)+'" text-anchor="middle">'+d.l+'</text>';
  });
  return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:'+H+'px">'+g+'</svg>';
}

/* ================= SHELL / NAV ================= */
function buildMenu(){
  var q=(document.getElementById('sbSearch').value||'').toLowerCase();
  var h='';
  var favItems=[];
  MENU.forEach(function(g){g.items.forEach(function(i){if(FAVS.indexOf(i.id)>-1&&HIDDEN.indexOf(i.id)<0)favItems.push(i);});});
  if(favItems.length){ h+='<div class="grp">★ Favourites</div>'+favItems.map(function(i){return mItem(i);}).join(''); }
  MENU.forEach(function(g){
    var items=g.items.filter(function(i){return HIDDEN.indexOf(i.id)<0&&(!q||i.t.toLowerCase().indexOf(q)>-1||i.n.toLowerCase().indexOf(q)>-1);});
    if(!items.length)return;
    h+='<div class="grp">'+g.g+'</div>'+items.map(function(i){return mItem(i);}).join('');
  });
  document.getElementById('menu').innerHTML=h;
}
function mItem(i){
  var b=i.badge?i.badge():0;
  return '<div class="mi '+(CUR===i.id?'on':'')+'" data-tip="'+i.t+'" onclick="go(\''+i.id+'\')">'+
    '<span class="ic" style="background:'+i.c+'22;color:'+(i.c==='#C9D3CD'?'#5C6B63':i.c)+'">'+i.ic+'</span>'+
    '<span class="tx">'+i.t+'</span>'+
    (b?'<span class="bdg">'+b+'</span>':'')+
    '<span class="st '+(FAVS.indexOf(i.id)>-1?'fav':'')+'" onclick="event.stopPropagation();toggleFav(\''+i.id+'\')">'+(FAVS.indexOf(i.id)>-1?'★':'☆')+'</span></div>';
}
function toggleFav(id){
  var ix=FAVS.indexOf(id); if(ix>-1)FAVS.splice(ix,1); else FAVS.push(id);
  buildMenu(); if(CUR==='settings')render();
  toast('Favourites updated',FAVS.length+' item(s) pinned.');
}
function toggleHide(id){
  var ix=HIDDEN.indexOf(id); if(ix>-1)HIDDEN.splice(ix,1); else HIDDEN.push(id);
  if(HIDDEN.indexOf(CUR)>-1)go('command');
  buildMenu(); if(CUR==='settings')render();
}
function filterMenu(){buildMenu();}
function go(id){CUR=id; buildMenu(); render(); closeDrawer(); if(window.scrollTo)window.scrollTo(0,0);}
function toggleSidebar(){

    var sidebar = document.getElementById('sidebar');
    if(!sidebar) return;

    /* Mobile uses the drawer flow, not desktop mini mode. */
    if(window.innerWidth<=860){
        toggleDrawer();
        return;
    }

    var isMini = sidebar.classList.toggle('mini');

    var btn = sidebar.querySelector('.sb-toggle');
    if(btn){
        btn.innerHTML = isMini ? '⇥' : '⇤';
        btn.title = isMini ? 'Expand menu' : 'Collapse menu';
        btn.setAttribute('aria-expanded', isMini ? 'false' : 'true');
    }

    /* Keep layout synchronized after width transition only.
       This does NOT change sidebar state. */
    setTimeout(syncSidebarLayout,230);
}
function toggleDrawer(){
  var sb=document.getElementById('sidebar'), sc=document.getElementById('sbScrim');
  if(!sb)return;
  var open=sb.classList.toggle('open');
  if(sc)sc.classList.toggle('on',open);
  document.body.style.overflow=open?'hidden':'';
}
function closeDrawer(){
  var sb=document.getElementById('sidebar'), sc=document.getElementById('sbScrim');
  if(sb)sb.classList.remove('open'); if(sc)sc.classList.remove('on');
  document.body.style.overflow='';
}
/* ============================================================
   SIDEBAR — MANUAL COLLAPSE / EXPAND ONLY
   No idle auto-close. No hover/mouse/keyboard auto-expand.
   The top .sb-toggle button is the only desktop state control.
   ============================================================ */

/* Kept as harmless compatibility stubs in case older markup/settings
   still references these names. They NEVER change sidebar state. */
function toggleAuto(){
  return false;
}

function armAuto(){
  return false;
}

/* Ctrl/Cmd + K may focus sidebar search only while already expanded.
   It must not expand a collapsed sidebar. */
document.addEventListener('keydown',function(e){
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='k'){
    var sidebar=document.getElementById('sidebar');
    var search=document.getElementById('sbSearch');

    if(sidebar && search && !sidebar.classList.contains('mini')){
      e.preventDefault();
      search.focus();
    }
  }

  if(e.key==='Escape'){
    closeModal();
    closeDrawer();
  }
});

/* ================= FILTERS ================= */
function buildFilters(){
  var cs=document.getElementById('fCluster');
  cs.innerHTML='<option value="ALL">All Clusters</option>'+
    CLUSTERS.map(function(c){return '<option value="'+c.id+'">'+c.name+' — '+c.br.length+' br</option>';}).join('');
  clusterChanged();
}
function clusterChanged(){
  var c=document.getElementById('fCluster').value, bs=document.getElementById('fBranch');
  var list=c==='ALL'?BR:BR.filter(function(b){return b.cl===c;});
  bs.innerHTML='<option value="ALL">All Branches</option>'+list.map(function(b){return '<option value="'+b.c+'">'+b.n+' ('+b.c+')</option>';}).join('');
}
function periodChanged(){
  var p=document.getElementById('fPeriod').value;
  var today=new Date();
  var iso=function(d){return d.getFullYear()+'-'+('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);};
  // Company billing cycle runs 6th of a month -> 5th of the next month.
  // Cycle "start month" = this month if today >= 6th, else previous month.
  var cyc=function(offset){
    var anchor=new Date(today.getFullYear(),today.getMonth(),today.getDate());
    var sMonth=anchor.getMonth();
    var sYear=anchor.getFullYear();
    if(anchor.getDate()<6){ sMonth=sMonth-1; }
    sMonth=sMonth+(offset||0);
    var start=new Date(sYear,sMonth,6);
    var end=new Date(sYear,sMonth+1,5);
    return [start,end];
  };
  var curCyc=cyc(0);
  var map={};
  map.today=[iso(today),iso(today)];
  var y=new Date(today);y.setDate(y.getDate()-1);map.yest=[iso(y),iso(y)];
  var w=new Date(today);w.setDate(w.getDate()-6);map.l7=[iso(w),iso(today)];
  // "This Month (MTD)" = current billing cycle start (6th) -> today
  map.mtd=[iso(curCyc[0]),iso(today)];
  // "Last Month" = previous full billing cycle (6th -> 5th)
  var prev=cyc(-1);
  map.lm=[iso(prev[0]),iso(prev[1])];
  var qm=today.getMonth()-(today.getMonth()%3);map.qtd=[iso(new Date(today.getFullYear(),qm,6)),iso(today)];
  var fyY=today.getMonth()>=3?today.getFullYear():today.getFullYear()-1;map.ytd=[iso(new Date(fyY,3,6)),iso(today)];
  if(map[p]){document.getElementById('fFrom').value=map[p][0];document.getElementById('fTo').value=map[p][1];}
}
function chips(){

  var p = document.getElementById('fPeriod');
  var c = document.getElementById('fCluster');
  var b = document.getElementById('fBranch');

  function shortDate(value){

    if(!value){
      return '';
    }

    var parts = value.split('-');

    if(parts.length !== 3){
      return value;
    }

    var months = [
      'Jan','Feb','Mar','Apr','May','Jun',
      'Jul','Aug','Sep','Oct','Nov','Dec'
    ];

    var year  = parts[0].slice(-2);
    var month = months[parseInt(parts[1],10) - 1];
    var day   = parts[2];

    return day + '-' + month + '-' + year;
  }


  var fromDate = shortDate(
    document.getElementById('fFrom').value
  );

  var toDate = shortDate(
    document.getElementById('fTo').value
  );


  document.getElementById('chipline').innerHTML =

    '<span class="chip">' +
      p.options[p.selectedIndex].text +
    '</span>' +

    '<span class="chip">' +
      fromDate +
      ' → ' +
      toDate +
    '</span>' +

    '<span class="chip">' +
      c.options[c.selectedIndex].text +
    '</span>' +

    '<span class="chip">' +
      b.options[b.selectedIndex].text +
    '</span>' +

    '<span class="chip g">Amounts: ' +
      ({
        A:'Auto',
        F:'Full ₹',
        K:'Thousands',
        L:'Lakhs',
        C:'Crore'
      }[AMTMODE]) +
    '</span>';
}
