function initRebooking(root_element){
  (function () {
    const fromInput    = root_element.querySelector(".from-date");
    const toInput      = root_element.querySelector(".to-date");
    const applyBtn     = root_element.querySelector(".apply-btn");
    const thisMonthBtn = root_element.querySelector(".this-month-btn");
    const lastMonthBtn = root_element.querySelector(".last-month-btn");

    const sdHeader = root_element.querySelector(".sd-header");
    const sdSub    = root_element.querySelector(".sd-sub");
    const sdThead  = root_element.querySelector(".sd-thead");
    const sdBody   = root_element.querySelector(".sd-body");

    if (!fromInput || !toInput || !sdBody) return;

    const MONTH_NAMES = ["Jan","Feb","Mar","April","May","June","July","Aug","Sep","Oct","Nov","Dec"];
    const EXCLUDED_BRANCHES = ["Head Office", "Testing Branch"];
    const GST_RATE = 0.05;

    function isExistingClient(media, alreadyTaken) {
      return (media || "").toLowerCase() === "existing customer" || alreadyTaken == 1;
    }
    function removeGST(v) { return (v || 0) / (1 + GST_RATE); }
    function extractInvoiceFromRemarks(remarks) {
      if (!remarks) return null;
      const match = remarks.match(/against Sales Invoice\s+([\w-]+)/i);
      return match ? match[1] : null;
    }

    let BRANCH_ORDER = [];

    initDefaultDates();
    bindEvents();
    loadData();

    function bindEvents() {
      applyBtn.onclick     = function () { clearActive(); loadData(); };
      thisMonthBtn.onclick = function () { setThisMonthRange(); setActive(thisMonthBtn); loadData(); };
      lastMonthBtn.onclick = function () { setLastMonthRange(); setActive(lastMonthBtn); loadData(); };
    }
    function initDefaultDates() { setThisMonthRange(); setActive(thisMonthBtn); }
    function setActive(btn) { clearActive(); if (btn) btn.classList.add("active"); }
    function clearActive() {
      root_element.querySelectorAll(".quick-btn").forEach(function(b){ b.classList.remove("active"); });
    }
    function fmtDate(d) {
      const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, "0"), day = String(d.getDate()).padStart(2, "0");
      return y + "-" + m + "-" + day;
    }
    function setThisMonthRange() {
      const now = new Date();
      let cycleYear = now.getFullYear();
      let cycleMonth = now.getMonth();
      if (now.getDate() < 6) cycleMonth -= 1;
      fromInput.value = fmtDate(new Date(cycleYear, cycleMonth, 6));
      toInput.value   = fmtDate(now);
    }
    function setLastMonthRange() {
      const now = new Date();
      let cycleYear = now.getFullYear();
      let cycleMonth = now.getMonth();
      if (now.getDate() < 6) cycleMonth -= 1;
      fromInput.value = fmtDate(new Date(cycleYear, cycleMonth - 1, 6));
      toInput.value   = fmtDate(new Date(cycleYear, cycleMonth, 5));
    }
    function monthShort(dateStr) { return MONTH_NAMES[new Date(dateStr).getMonth()]; }
    function dayOf(dateStr) { return new Date(dateStr).getDate(); }
    function year2(dateStr) { return new Date(dateStr).getFullYear().toString().slice(-2); }

    async function fetchBranches() {
      const res = await frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Branch", fields: ["name"],
          filters: [["name", "not in", EXCLUDED_BRANCHES]],
          order_by: "name asc", limit_page_length: 1000 }
      });
      return (res.message || []).map(function(b){ return b.name; });
    }
    async function fetchTargets(fromStr, toStr) {
      const targets = {};
      let res = await frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Week Target vs Achive With Cuttings",
          filters: [["from_date", "=", fromStr], ["to_date", "=", toStr]],
          fields: ["name"], limit_page_length: 1, order_by: "creation desc" }
      });
      let docname = (res.message || [])[0] && res.message[0].name;
      if (!docname) {
        res = await frappe.call({
          method: "frappe.client.get_list",
          args: { doctype: "Week Target vs Achive With Cuttings",
            filters: [["from_date", "<=", toStr], ["to_date", ">=", fromStr]],
            fields: ["name"], limit_page_length: 1, order_by: "creation desc" }
        });
        docname = (res.message || [])[0] && res.message[0].name;
      }
      if (!docname) return { targets: targets, source: null };
      const docRes = await frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Week Target vs Achive With Cuttings", name: docname }
      });
      (docRes.message.week_target_vs_archive_details || []).forEach(function(row){
        targets[row.branch] = row.targeted_amount || 0;
      });
      return { targets: targets, source: docname };
    }
    async function fetchPaymentEntries(fromStr, toStr) {
      const res = await frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Payment Entry",
          filters: [["posting_date", "between", [fromStr, toStr]],
            ["docstatus", "=", 1], ["payment_type", "=", "Receive"],
            ["branch", "not in", EXCLUDED_BRANCHES]],
          fields: ["name", "branch", "paid_amount", "remarks"], limit_page_length: 0 }
      });
      return res.message || [];
    }
    async function fetchInvoiceTherapyMap(invoiceNames) {
      if (!invoiceNames.length) return {};
      const res = await frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Sales Invoice", filters: [["name", "in", invoiceNames]],
          fields: ["name", "therapy_plan_reference_id", "custom_therapy_plan"], limit_page_length: 0 }
      });
      const map = {};
      (res.message || []).forEach(function(r){ map[r.name] = r.therapy_plan_reference_id || r.custom_therapy_plan || null; });
      return map;
    }
    async function fetchTherapyPlanMap(planNames) {
      if (!planNames.length) return {};
      const res = await frappe.call({
        method: "frappe.client.get_list",
        args: { doctype: "Therapy Plan", filters: [["name", "in", planNames]],
          fields: ["name", "media", "therapy_plan_already_taken_"], limit_page_length: 0 }
      });
      const map = {};
      (res.message || []).forEach(function(r){ map[r.name] = isExistingClient(r.media, r.therapy_plan_already_taken_); });
      return map;
    }

    async function loadData() {
      sdBody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:14px;color:#888;">Loading…</td></tr>';
      try {
        const from = fromInput.value, to = toInput.value;
        const curMon = monthShort(to);
        const yr     = year2(to);

        const arr = await Promise.all([ fetchBranches(), fetchTargets(from, to), fetchPaymentEntries(from, to) ]);
        const branches = arr[0], targetData = arr[1], paymentEntries = arr[2];
        BRANCH_ORDER = branches;

        const peInvoiceMap = {};
        paymentEntries.forEach(function(pe){
          const inv = extractInvoiceFromRemarks(pe.remarks);
          if (inv) peInvoiceMap[pe.name] = inv;
        });

        const invoiceNames = Array.from(new Set(Object.values(peInvoiceMap)));
        const invTherapyMap = await fetchInvoiceTherapyMap(invoiceNames);
        const planNames = Array.from(new Set(Object.values(invTherapyMap).filter(Boolean)));
        const therapyPlanMap = await fetchTherapyPlanMap(planNames);

        const branchMap = {};
        BRANCH_ORDER.forEach(function(b){ branchMap[b] = { newPaid: 0, existingPaid: 0 }; });

        paymentEntries.forEach(function(pe){
          const branch = pe.branch;
          if (EXCLUDED_BRANCHES.includes(branch)) return;
          if (!branchMap[branch]) branchMap[branch] = { newPaid: 0, existingPaid: 0 };
          const paid     = removeGST(pe.paid_amount);
          const invName  = peInvoiceMap[pe.name];
          const planName = invName ? invTherapyMap[invName] : null;
          const existing = planName ? (therapyPlanMap[planName] === true) : false;
          if (existing) branchMap[branch].existingPaid += paid;
          else          branchMap[branch].newPaid      += paid;
        });

        sdHeader.textContent = "New & Existing Client Wise Sale Report — " + curMon + "'" + yr;
        sdSub.textContent    = dayOf(from) + " – " + dayOf(to) + " " + curMon + " " + new Date(to).getFullYear() + (targetData.source ? "  |  Target: " + targetData.source : "  |  No target record found");

        buildTable(branchMap, targetData.targets || {});
      } catch (err) {
        void 0;
        sdBody.innerHTML = '<tr><td colspan="8" style="color:red;text-align:center;padding:12px;">Error: ' + (err.message || err) + '</td></tr>';
      }
    }

    function buildTable(branchMap, targets) {
      const branches = Array.from(new Set([].concat(BRANCH_ORDER, Object.keys(branchMap).filter(function(b){ return !EXCLUDED_BRANCHES.includes(b); }))));
      sdThead.innerHTML = '<tr><th>Branch</th><th>Target (With GST)</th><th>Ached</th><th>Ach %</th><th>New Client Sale</th><th>New Client %</th><th>Existing Client Sale</th><th>Existing Client %</th></tr>';
      let totTarget = 0, totAched = 0, totNew = 0, totExisting = 0;
      let html = "";
      branches.forEach(function(b){
        const d            = branchMap[b] || { newPaid: 0, existingPaid: 0 };
        const target       = targets[b] || 0;
        const ached        = d.newPaid + d.existingPaid;
        const achedWithGst = ached * (1 + GST_RATE);
        const achPct       = target > 0 ? Math.round(achedWithGst / target * 100) : 0;
        const newPct       = ached > 0 ? Math.round(d.newPaid      / ached * 100) : 0;
        const exPct        = ached > 0 ? Math.round(d.existingPaid / ached * 100) : 0;
        totTarget   += target; totAched += ached; totNew += d.newPaid; totExisting += d.existingPaid;
        html += '<tr><td>' + b + '</td><td>' + fmt(target) + '</td><td>' + fmt(ached) + '</td><td class="ach-pct">' + achPct + '%</td><td>' + fmt(d.newPaid) + '</td><td class="pct-new">' + newPct + '%</td><td>' + fmt(d.existingPaid) + '</td><td class="pct-existing">' + exPct + '%</td></tr>';
      });
      const totAchedWithGst = totAched * (1 + GST_RATE);
      const totAchPct = totTarget > 0 ? Math.round(totAchedWithGst / totTarget * 100) : 0;
      const totNewPct = totAched  > 0 ? Math.round(totNew / totAched * 100) : 0;
      const totExPct  = totAched  > 0 ? Math.round(totExisting / totAched * 100) : 0;
      html += '<tr class="total-row"><td>TOTAL</td><td>' + fmt(totTarget) + '</td><td>' + fmt(totAched) + '</td><td>' + totAchPct + '%</td><td>' + fmt(totNew) + '</td><td>' + totNewPct + '%</td><td>' + fmt(totExisting) + '</td><td>' + totExPct + '%</td></tr>';
      sdBody.innerHTML = html;
    }
    function fmt(v) { return Math.round(v || 0).toLocaleString("en-IN"); }
  })();
}

