function pgTestSale(){
  var head = phead('Sale \u2014 Testing 🧪',
    'WORKING ON \u2014 NOT YET COMPLETED. Filter is on Paid date. Per branch and media: Package Amount (total package amount, no cuts), Outstanding (live unpaid balance), New collection (invoice inside range) and Old collection (invoice before range).');

  var banner = '<div style="background:#FDECEC;border:1px solid #E4A0A0;color:#8A2E2E;padding:10px 14px;border-radius:8px;margin:6px 0 14px;font-weight:600">\u26A0 Testing \u2014 figures under verification. Do not use for reporting yet.</div>';

  if(!TSALE.on) return head+banner+emptyBox('Loading testing data\u2026');

  var data=TSALE.data||{};
  var branches=[];
  for(var b in data){ if(data.hasOwnProperty(b)) branches.push(b); }
  if(!branches.length) return head+banner+emptyBox('No data for the selected range.');
  branches.sort();

  var html='';
  var GG=0,GN=0,GT=0,GO=0,GNew=0,GOld=0;

  branches.forEach(function(b){
    var media=data[b]; var mrows=[];
    var bG=0,bN=0,bT=0,bO=0,bNew=0,bOld=0;
