    mk.sort(function(x,y){ return (media[y].gross||0)-(media[x].gross||0); });
    mk.forEach(function(m){
      var x=media[m];
      mrows.push({c:[m,money(x.gross||0),money(x.outstanding||0),money(x.new_coll||0),money(x.old_coll||0)]});
      bO+=x.outstanding||0; bG+=x.gross||0; bNew+=x.new_coll||0; bOld+=x.old_coll||0;
    });
    GG+=bG; GN+=bN; GT+=bT; GO+=bO; GNew+=bNew; GOld+=bOld;
    html+=sec(b,'Media-wise \u2014 paid-date filter',
      table([{t:'Media'},{t:'Package Amount',num:1},{t:'Outstanding',num:1},{t:'New Collection',num:1},{t:'Old Collection',num:1}],
        mrows,['BRANCH TOTAL',money(bG),money(bO),money(bNew),money(bOld)]));
  });

  var grand=sec('Company Total','All branches, all media',
    table([{t:''},{t:'Package Amount',num:1},{t:'Outstanding',num:1},{t:'New Collection',num:1},{t:'Old Collection',num:1}],
      [{c:['TOTAL',money(GG),money(GO),money(GNew),money(GOld)]}],null),'gold');

  return head+banner+grand+html+
    '<div class="note-s">Package Amount = total package amount (SI grand total, no cuts), counted once per invoice touched in range. Outstanding = live unpaid balance of those invoices. New collection = invoice posting date inside range; Old collection = invoice posting date before From date. Filter on paid date.</div>';
}
function scoreAuditFor(name){
  if(!AUD.on) return null;
  for(var i=0;i<AUD.branches.length;i++){ if(norm(AUD.branches[i].branch)===norm(name)) return +(AUD.branches[i].pct||0); }
  return null;
}
function scoreTargetFor(name){
  if(!ACC.on) return null;
  for(var i=0;i<ACC.targets.length;i++){ if(norm(ACC.targets[i].branch)===norm(name)) return +(ACC.targets[i].pct||0); }
  return null;
}
function pgScore(){
  if(!BR.length) return phead('Branch Scorecard','Live league table across branches.')+
    sec('Scorecard','',emptyBox('Loading live branch data…'));

  // Build rows from live data only
  var rows=BR.map(function(b){
    var pkg=b.gsale||0, coll=b.coll||0, dues=b.duesAmt||0, staff=b.staff||0;
    var tgtPct=scoreTargetFor(b.n);          // may be null if no target sheet
    var collPct=pkg>0?(coll/pkg*100):0;
    var audit=scoreAuditFor(b.n);            // may be null if no audit
    var revHead=staff>0?(pkg/staff):0;
    return {b:b, pkg:pkg, coll:coll, dues:dues, staff:staff,
            tgtPct:tgtPct, collPct:collPct, audit:audit, revHead:revHead};
  });

  // Normalise each live metric to 0-100 across branches, then equal-weight.
  // Metrics: Target% (higher better), Collection% (higher better),
  //          Dues (lower better -> invert), Audit (higher better).
  function maxOf(key){ var mx=0; rows.forEach(function(r){ var v=r[key]; if(v!==null&&v>mx)mx=v; }); return mx||1; }
  var duesMax=maxOf('dues');
  rows.forEach(function(r){
    var parts=[], w=[];
    if(r.tgtPct!==null){ parts.push(Math.min(100,r.tgtPct)); }
    parts.push(Math.min(100,r.collPct));
    parts.push(duesMax>0?(100-(r.dues/duesMax*100)):100);   // low dues = high score
    if(r.audit!==null){ parts.push(Math.min(100,r.audit)); }
    var sum=0; for(var i=0;i<parts.length;i++){ sum+=parts[i]; }
    r.index=parts.length?(sum/parts.length):0;
  });

  rows.sort(function(a,b){ return b.index-a.index; });

  // KPI summary
  var best=rows[0], worst=rows[rows.length-1];
  var avgIdx=rows.reduce(function(s,r){return s+r.index;},0)/(rows.length||1);
  var kp='<div class="kgrid">'+
    kpi('Branches Ranked',rows.length,'Live, equal-weighted index','b','',"")+
    kpi('Top Branch',best?best.b.n:'—',best?('Index '+best.index.toFixed(1)):'','g','',"")+
    kpi('Needs Attention',worst?worst.b.n:'—',worst?('Index '+worst.index.toFixed(1)):'','a','',"")+
    kpi('Average Index',avgIdx.toFixed(1),'Across all branches','','',"")+
  '</div>';

  // League table
  var cols=[{t:'Rank'},{t:'Branch'},{t:'Index',num:1},{t:'Target %',num:1},{t:'Coll %',num:1},
            {t:'Dues',num:1},{t:'Audit',num:1},{t:'Pkg / Head',num:1},{t:'Verdict'}];
  var trows=rows.map(function(r,i){
    var idxCls=r.index>=75?'p-ok':r.index>=55?'p-wn':'p-al';
    var verdict=r.index>=75?'Strong':r.index>=55?'Steady':'Watch';
    var rank=(i+1);
    var medal=rank===1?'🥇':rank===2?'🥈':rank===3?'🥉':String(rank);
    return {c:[
      medal,
      d2(r.b.n, r.b.cl==='AP'?'Andhra':'Telangana'),
      '<span class="pill '+idxCls+'">'+r.index.toFixed(1)+'</span>',
      r.tgtPct!==null?pc(r.tgtPct,0):'—',
      pc(r.collPct,0),
      mL(r.dues),
      r.audit!==null?pc(r.audit,0):'—',
      r.staff>0?mL(r.revHead):'—',
      '<span class="pill '+idxCls+'">'+verdict+'</span>'
    ]};
  });
  var tbl=table(cols,trows,null);

  var method='<div class="note-s" style="line-height:1.8">'+
    '<b>Index</b> = equal-weighted average of the live metrics available for each branch, each scaled 0–100:<br>'+
    '<b>Target %</b> (achievement vs weekly target sheet) · <b>Collection %</b> (collections ÷ package amount) · '+
    '<b>Dues</b> (lower is better — scored against the highest-dues branch) · <b>Audit</b> (latest audit score).<br>'+
    'A branch with no target sheet or no audit for the period is scored on the metrics it does have, so the index stays fair. '+
    'All figures are live from the portal for the selected date range — nothing is hard-coded.</div>';

  return phead('Branch Scorecard',
    'A live league table ranking every branch on target achievement, collections, dues and audit — equal weighted, for the selected period.')
   +kp
   +sec('The League Table','Ranked by live index',tbl,'gold')
   +sec('How the Index Is Built','Transparent, live-only method',method,'blue');
}

function pgCash(){
  if(!CASH.on) return phead('Cash & Treasury','Live cash and bank balances, and receivables ageing.')+
    sec('Cash & Treasury','',emptyBox('Loading treasury & ageing… (needs md_cash_api)'));

  var tr=CASH.treasury||{}, at=CASH.ageing_totals||{};
  var kp='<div class="kgrid">'+
    kpi('Total Treasury (today)',mC(tr.total_today||0),(tr.account_count||0)+' cash + bank accounts','g','',"")+
    kpi('Bank Balance (today)',mC(tr.bank_today||0),'As of '+(CASH.today||'today'),'b')+
    kpi('Cash in Hand (today)',mC(tr.cash_today||0),'All cash accounts','')+
    kpi('Total Receivables',mC(at.total||0),(at.bills||0)+' open bills','a','',"")+
    kpi('Overdue Receivables',mC(at.overdue||0),'Past due date',(at.overdue>0?'a':''),(at.overdue>0?'<span class="kt d">!</span>':''))+
    kpi('60+ Days Dues',mC(at.b3||0),'Oldest bucket','a')+
  '</div>';

  // Treasury accounts table (grouped Bank then Cash)
  var accts=CASH.accounts||[];
  var banks=accts.filter(function(a){return a.type==='Bank';});
  var cash =accts.filter(function(a){return a.type==='Cash';});
  function acctTbl(list,label){
    if(!list.length) return emptyBox('No '+label+' accounts with a balance.');
    var st=0,sa=0;
    var rows=list.map(function(a){
      st+=a.today||0; sa+=a.asof||0;
      var drift=(a.today||0)-(a.asof||0);
      return {c:[a.account, mL(a.asof||0), mL(a.today||0),
        '<span style="color:'+(drift>=0?'var(--pos)':'var(--alert)')+'">'+(drift>=0?'+':'')+mL(drift)+'</span>']};
    });
    return table([{t:label+' Account'},{t:'As of '+(CASH.as_on||''),num:1},{t:'Today',num:1},{t:'Change',num:1}],
      rows,['TOTAL',mL(sa),mL(st),'']);
  }
  function branchCashTbl(){
    var list=CASH.branch_cash||[];
    if(!list.length) return emptyBox('No branch-wise cash/bank balances.');
    var sC=0,sB=0,sT=0;
    var rows=list.map(function(r){
      sC+=r.cash_today||0; sB+=r.bank_today||0; sT+=r.total_today||0;
      return {c:[
        d2(r.branch,''),
        mL(r.cash_today||0),
        mL(r.bank_today||0),
        '<b>'+mL(r.total_today||0)+'</b>',
        mL(r.total_asof||0)
      ]};
    });
    return '<h4 style="margin:6px 0 6px 2px;color:var(--deep)">🏢 Cash &amp; Bank by Branch (cost centre) — today</h4>'+
      table([{t:'Branch'},{t:'Cash',num:1},{t:'Bank',num:1},{t:'Total (today)',num:1},{t:'As of '+(CASH.as_on||''),num:1}],
        rows,['ALL BRANCHES',mL(sC),mL(sB),mL(sT),'']);
  }
  var treasuryBody=
    '<div class="note-s" style="margin:0 0 8px 2px">Balance = live GL (debit − credit) up to each date. '+
    '"As of" = the report To-date ('+(CASH.as_on||'')+'); "Today" = '+(CASH.today||'')+'. '+
    'Cash sits in shared ledgers split by branch (cost centre) — the branch table below shows how much cash each branch holds.</div>'+
    branchCashTbl()+
    '<h4 style="margin:16px 0 6px 2px;color:var(--deep)">🏦 Bank (by account)</h4>'+acctTbl(banks,'Bank')+
    '<h4 style="margin:14px 0 6px 2px;color:var(--deep)">💵 Cash (by account)</h4>'+acctTbl(cash,'Cash');

  // Ageing table per branch
  var age=CASH.ageing||[];
  var ageBody;
  if(age.length){
    var rows=age.map(function(r){
      return {c:[
        d2(r.branch, r.bills+' bill'+(r.bills===1?'':'s')),
        mL(r.current||0), mL(r.b1||0), mL(r.b2||0),
        '<span style="color:'+((r.b3>0)?'var(--alert)':'inherit')+'">'+mL(r.b3||0)+'</span>',
        '<b>'+mL(r.total||0)+'</b>',
        (r.overdue>0?'<span class="pill p-al">'+mL(r.overdue)+'</span>':'<span class="pill p-ok">—</span>')
      ]};
    });
    var at2=CASH.ageing_totals||{};
    ageBody=table(
      [{t:'Branch'},{t:'Current',num:1},{t:'1–30 d',num:1},{t:'31–60 d',num:1},{t:'60+ d',num:1},{t:'Total Dues',num:1},{t:'Overdue'}],
      rows,
      ['ALL',mL(at2.current||0),mL(at2.b1||0),mL(at2.b2||0),mL(at2.b3||0),mL(at2.total||0),
       (at2.overdue>0?'<span class="pill p-al">'+mL(at2.overdue)+'</span>':'—')]);
  } else {
    ageBody=emptyBox('No outstanding receivables. 🎉');
  }

  return phead('Cash & Treasury',
    'Live cash and bank position (today and as of the report date) across every cash/bank account, plus receivables ageing by branch with an overdue flag. Balances from the General Ledger; dues from open Sales Invoices.')
   +kp
   +sec('Treasury — Cash & Bank Balances','Live GL balance · Bank then Cash',treasuryBody,'gold')
   +sec('Receivables Ageing by Branch','Current / 1–30 / 31–60 / 60+ · overdue flagged',ageBody,'blue')
   +sec('Notes','How these are computed',
     '<div class="note-s" style="line-height:1.8">'+
     '<b>Treasury</b> sums the General Ledger movement (debit − credit) on every non-cancelled entry up to the date, for each account tagged Cash or Bank. Accounts with a zero balance on both dates are hidden.<br>'+
     '<b>Receivables ageing</b> buckets each open invoice\u2019s outstanding by the age of its posting date as of '+(CASH.as_on||'the report date')+'. <b>Overdue</b> = invoices past their due date. Dues are the live outstanding balance, so paying a bill later reduces it.</div>','plum');
}

