/* ---- Target & Realisation (BCC-style): cluster-wise + branch-wise ---- */
function targetRealisation(){
  if(!ACC.on) return emptyBox('Loading targets… (needs md_accounts_api)');
  if(!ACC.targets.length) return emptyBox('No target sheet overlaps this cycle. Add a Week Target document covering '+(LIVE.from||'')+' → '+(LIVE.to||'')+'.');

  // days-left within the 6th->5th cycle, for "needed/day"
  var dLeft=1;
  if(LIVE.to){var parts=LIVE.to.split('-').map(Number),asOf=new Date(parts[0],parts[1]-1,parts[2]),end=new Date(parts[0],parts[1]-1+(parts[2]>=6?1:0),5);dLeft=Math.max(1,Math.round((end-asOf)/86400000));}

  // cluster cards
  var cl='<div class="split3" style="margin-bottom:12px">'+ACC.clusters.map(function(c){
    var pct=c.pct||0; var gap=Math.max(0,(c.target||0)-(c.achieved||0));
    var tone=pct>=100?'ok':pct>=85?'':pct>=70?'y':'r';
    var trkCls=pct>=85?'p-ok':pct>=70?'p-wn':'p-al';
    var trk=pct>=100?'Target met':pct>=85?'On track':'Behind';
    return '<div class="mini" style="cursor:pointer" onclick="clusterModal(\''+c.id+'\')">'+
      '<h4>'+c.name+' <em>'+pc(pct,0)+'</em></h4>'+
      '<div class="note-s" style="margin:0 0 7px 0">'+c.heads+'</div>'+
      '<div style="font-family:Georgia,serif;font-size:19px;color:var(--deep)">'+mL(c.achieved)+' <span style="font-size:12px;color:var(--muted)">of '+mL(c.target)+'</span></div>'+
      barpc(pct,120,tone==='ok'||tone===''?'':tone==='y'?'y':'r')+
      '<div style="display:flex;justify-content:space-between;margin-top:7px;font-size:12px">'+
        '<span>Gap <b>'+mL(gap)+'</b></span><span class="pill '+trkCls+'">'+trk+'</span></div>'+
    '</div>';}).join('')+'</div>';

  // branch-wise table (BCC Target & Realisation style)
  var rows=[].concat(ACC.targets).filter(function(b){return b.target>0;})
    .sort(function(a,b){return b.pct-a.pct;}).map(function(b){
    var gap=Math.max(0,(b.target||0)-(b.achieved||0));
    var perDay=gap/dLeft;
    var trkCls=b.pct>=100?'p-ok':b.pct>=85?'p-ok':b.pct>=70?'p-wn':'p-al';
    var trk=b.pct>=100?'Met':b.pct>=85?'On track':'Behind';
    return {click:"branchTargetModal('"+norm(b.branch)+"')",c:[
      d2(b.branch,b.cluster==='AP'?'Andhra':'Telangana'),
      mL(b.target),mL(b.achieved),
      '<span class="pill '+(b.pct>=100?'p-ok':b.pct>=85?'p-ok':b.pct>=70?'p-wn':'p-al')+'">'+pc(b.pct,0)+'</span>',
      mL(gap), mL(perDay),
      barpc(b.pct,120,b.pct>=100?'':b.pct>=85?'':b.pct>=70?'y':'r'),
      '<span class="pill '+trkCls+'">'+trk+'</span>']};});
  var tot=ACC.totals;
  var totGap=Math.max(0,(tot.target||0)-(tot.achieved||0));
  var branchTbl=table(
    [{t:'Branch'},{t:'Target',num:1},{t:'Achieved',num:1},{t:'Achieved %',num:1},{t:'Still to Collect',num:1},{t:'Per Day Needed',num:1},{t:'Progress'},{t:'Status'}],
    rows,
    ['ALL',mL(tot.target||0),mL(tot.achieved||0),pc(tot.pct||0,0),mL(totGap),mL(totGap/dLeft),'','']);

  return cl+'<div class="note-s" style="margin:0 0 8px 2px">'+dLeft+' day(s) left in cycle · "Needed / day" = remaining gap ÷ days left. Click a branch for detail.</div>'+branchTbl;
}
function branchTargetModal(nkey){
  var b=null; for(var i=0;i<ACC.targets.length;i++){ if(norm(ACC.targets[i].branch)===nkey) b=ACC.targets[i]; }
  if(!b)return;
  var bn=b.branch;
  // open immediately with a loading body, then fetch daily detail
  openModal('Target vs Achieved — '+bn+' <span style="font-size:12px;opacity:.8">· '+(LIVE.from||'')+' → '+(LIVE.to||'')+'</span>',
    '<div class="empty">Loading daily target tracker…</div>');
  var u='/api/method/md_target_daily_api?branch='+encodeURIComponent(bn);
  if(LIVE.to) u+='&to_date='+LIVE.to;
  fetch(u,{headers:{'Accept':'application/json'},credentials:'same-origin'})
    .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
    .then(function(j){ renderTargetModal(j.message||j, b); })
    .catch(function(err){ renderTargetModalFallback(b, err.message); });
}
function renderTargetModalFallback(b, msg){
  var gap=Math.max(0,(b.target||0)-(b.achieved||0));
  document.getElementById('mBody').innerHTML=
   '<div class="mstat">'+
     '<div><div class="l">Target</div><div class="v">'+money(b.target)+'</div></div>'+
     '<div><div class="l">Achieved</div><div class="v">'+money(b.achieved)+'</div></div>'+
     '<div><div class="l">Achieved %</div><div class="v">'+pc(b.pct,1)+'</div></div>'+
     '<div><div class="l">Gap</div><div class="v">'+money(gap)+'</div></div>'+
   '</div>'+
   '<div class="note-s">Daily tracker unavailable ('+(msg||'')+'). Install md_target_daily_api to enable the day-by-day view.</div>';
}
function renderTargetModal(T, b){
  if(!T || !T.days){ renderTargetModalFallback(b,'no daily data'); return; }
  var onTrack=!!T.on_track;
  var stat='<div class="mstat">'+
    '<div><div class="l">Achieved % (this month)</div><div class="v" style="color:'+(T.pct<70?'var(--alert)':T.pct<85?'var(--warn)':'var(--pos)')+'">'+pc(T.pct,1)+'</div></div>'+
    '<div><div class="l">Achieved (cycle)</div><div class="v">'+money(T.achieved)+'</div></div>'+
    '<div><div class="l">Monthly Target</div><div class="v">'+money(T.target)+'</div></div>'+
    '<div><div class="l">Gap to Close</div><div class="v" style="color:var(--alert)">'+money(T.gap)+'</div></div>'+
    '<div><div class="l">Needed / day</div><div class="v" style="color:var(--alert)">'+money(T.req_per_day)+'</div></div>'+
    '<div><div class="l">Days Left</div><div class="v">'+T.days_left+'</div></div>'+
  '</div>';
  var need='<div class="tgt-need '+(onTrack?'ok':'warn')+'">'+
    '<div class="l">To hit '+money(T.target)+' by '+T.cycle_to+'</div>'+
    '<div class="v">'+money(T.req_per_day)+'<span> / day</span></div>'+
    '<div class="s">'+money(T.gap)+' still to collect across '+T.days_left+' remaining day'+(T.days_left===1?'':'s')+'</div>'+
  '</div>';
  var rr='<div class="tgt-grid">'+
    '<div class="tgt-cell"><span>Current run rate</span><b>'+money(T.run_rate)+' / day</b></div>'+
    '<div class="tgt-cell"><span>Required run rate</span><b class="r">'+money(T.req_per_day)+' / day</b></div>'+
    '<div class="tgt-cell"><span>Projected at pace</span><b class="'+(onTrack?'':'r')+'">'+money(T.projected)+'</b></div>'+
    '<div class="tgt-cell"><span>Status</span><b class="'+(onTrack?'':'r')+'">'+(onTrack?'ON TRACK':'BEHIND by '+money(Math.max(T.target-T.projected,0)))+'</b></div>'+
    '<div class="tgt-cell"><span>Days hit</span><b>'+T.hit_days+'</b></div>'+
    '<div class="tgt-cell"><span>Days missed</span><b class="r">'+T.miss_days+'</b></div>'+
  '</div>';
  // elapsed days
  var elapsed=T.days.filter(function(d){return !d.future;});
  var mx=1; elapsed.forEach(function(d){ var m=Math.max(d.got,d.req); if(m>mx)mx=m; });
  var strip='<div class="tgt-strip">'+elapsed.map(function(d){
    var gh=Math.round((d.got/mx)*100), rh=Math.round((d.req/mx)*100);
    var dd=(''+d.d); dd=dd.substring(8,10);
    return '<div class="tgt-bar" title="'+d.d+' — collected '+money(d.got)+' of '+money(d.req)+'">'+
      '<div class="tgt-bar-wrap"><i class="'+(d.hit?'ok':'no')+'" style="height:'+gh+'%"></i>'+
      '<u style="bottom:'+rh+'%"></u></div><span>'+dd+'</span></div>';}).join('')+'</div>'+
    '<div class="tgt-legend"><span><i class="sw ok"></i>Hit</span><span><i class="sw no"></i>Miss</span><span><i class="sw line"></i>Required that day</span></div>';
  // day-by-day table (newest first)
  var rows=elapsed.slice().reverse();
  var tbl=rows.length?table(
    [{t:'Date'},{t:'Target that day',num:1},{t:'Collected',num:1},{t:'+/-',num:1},{t:'Cumulative',num:1},{t:'Result'}],
