    :emptyBox('No elapsed days in this cycle yet.');
  var formula='<div class="note-s" style="line-height:1.7">Uses the <b>deficit method</b>: each day\u2019s target = (monthly target \u2212 collected so far) \u00F7 days still remaining. A miss raises the bar for later days; a big day lowers it. Cycle <b>'+T.cycle_from+' \u2192 '+T.cycle_to+'</b> ('+T.total_days+' days, 6th\u21925th). Collections from Payment Entry.</div>';
  var gstK=b?gstKey(b.branch):'';
  var gstBtn=gstK?'<div style="margin-top:10px"><button class="btn gold" onclick="gstModal(\''+gstK.replace(/\x27/g,"")+'\')">💳 Payment-mode GST split ›</button></div>':'';
  document.getElementById('mBody').innerHTML=
    stat+need+
    sec('Pace check','',rr)+
    sec('Daily collections vs required',elapsed.length+' days',strip)+
    sec('Day by day — newest first',rows.length+' rows',tbl)+
    sec('How the daily target works','deficit method',formula,'gold')+
    gstBtn;
}
function gstModeTable(key){
  var modes=GST.data[key]; if(!modes) return '';
  var rows=[]; var tG=0,tN=0,tT=0;
  for(var m in modes){ if(modes.hasOwnProperty(m)){ var x=modes[m];
    rows.push({c:[m,money(x.total||0),money(x.net||0),money(x.gst||0)]}); tG+=x.total||0;tN+=x.net||0;tT+=x.gst||0; }}
  return table([{t:'Mode'},{t:'Package Amount',num:1},{t:'Net',num:1},{t:'GST',num:1}],rows,['TOTAL',money(tG),money(tN),money(tT)]);
}

