/* ============================================================
   APPROVAL ROUTING
   P2P  -> /package-conversion-for-p2p
   C2C  -> /package-conversion-C2C
   B2B  -> /client-b2b-transfer
   DISC -> /billing?tab=approvals

   The client name is taken from the live approval row. We pass both
   client_name and client so the destination page can support either
   parameter name. The approval id is also passed for exact drill-down.
   ============================================================ */
function approvalClientName(a){
  return (a && (a.cn || a.client || a.client_name || a.customer || a.title)) || '';
}

function approvalRoute(a){
  if(!a) return '#';

  var client = approvalClientName(a);
  var qs = 'approval_id=' + encodeURIComponent(a.id || '') +
           '&client_name=' + encodeURIComponent(client) +
           '&client=' + encodeURIComponent(client);

  if(a.src === 'P2P'){
    return '/package-conversion-for-p2p?' + qs;
  }

  if(a.src === 'C2C'){
    return '/package-conversion-C2C?' + qs;
  }

  if(a.src === 'B2B'){
    return '/client-b2b-transfer?' + qs;
  }

  if(a.src === 'DISC'){
    return '/billing?tab=approvals&' + qs;
  }

  return a.erp || '#';
}

function approvalOpenButton(a){
  var url=approvalRoute(a);
  return '<a class="btn sm" href="'+url+'" target="_blank" rel="noopener" onclick="event.stopPropagation()">Open ↗</a>';
}

function myApprovalsBlock(){
  if(!MYAP.on) return sec('Pending For You','','<div class="empty">Loading your queue…</div>','gold');
  var rows=MYAP.approvals;
  if(!rows.length) return sec('Pending For You','Nothing waiting',emptyBox('✅ No approvals are currently waiting on you ('+(MYAP.user||'')+').'),'gold');
  // group by source
  var srcName={P2P:'Package Conversion (P2P)',C2C:'Client Conversion (C2C)',B2B:'Branch Transfer (B2B)',DISC:'Discount (L4)',PI:'Purchase Invoice',PO:'Purchase Order'};
  var srcTone={P2P:'plum',C2C:'blue',B2B:'gold',DISC:'gold',PI:'gold',PO:'plum'};
  var groups={};
  rows.forEach(function(a){ if(!groups[a.src])groups[a.src]=[]; groups[a.src].push(a); });
  var body='';
  Object.keys(groups).forEach(function(k){
    var g=groups[k];
    var trows=g.map(function(a){
      var xfer=a.xfer?(' · '+a.xfer):'';
      var recv=a.recvBr?(' → '+a.recvBr):'';
      var actBtn='';
      if(a.src==='PI')actBtn='<button class="btn sm" onclick="event.stopPropagation();apprPI(\''+a.id+'\')">Review</button>';
      else if(a.src==='P2P'||a.src==='C2C'||a.src==='B2B'||a.src==='DISC')actBtn=approvalOpenButton(a);
      else actBtn='<a class="btn sm" href="'+(a.erp||'#')+'" target="_blank" rel="noopener" onclick="event.stopPropagation()">Open ↗</a>';      return {c:['<b>'+(a.title||a.id)+'</b>',a.cn+recv+xfer,a.br||'—',
        '<span class="pill p-wn">'+(a.stage||'')+'</span>',money(a.gross||0),
        '<span class="pill '+(a.forWho==='COO'?'p-nu':'p-al')+'">'+a.forWho+'</span>',actBtn]};});
    body+=sec(srcName[k]+' <span class="pill p-nu" style="margin-left:6px">'+g.length+'</span>','Waiting on you',
      table([{t:'Reference'},{t:'Client / Supplier'},{t:'Branch'},{t:'Stage'},{t:'Value',num:1},{t:'Desk'},{t:'Action'}],trows),
      srcTone[k]||'');
  });
  return body;
}

