   '<div style="font-size:13.5px;line-height:1.7">Invoice: <b>'+(d.invoice||'—')+'</b> · Branch: <b>'+(d.branch||'—')+'</b><br>'+
   'Raised by: '+(d.by||'—')+'<br>Reason: '+(d.reason||'—')+'</div>'+
   '<div class="note-s">Approving sets status <b>Approved</b> and stamps you as approver. Rejecting sets <b>Rejected</b>.</div></div>'+
   apprActions('disc',d.id,d.erp));
}
function apprActions(kind,id,erp){
  var canW=APR.can_write;
  var buttons = canW
    ? '<button class="btn primary" onclick="apprAct(\''+kind+'\',\''+id+'\',true)">✔ Approve</button>'+
      '<button class="btn" style="border-color:#B0392F;color:#B0392F" onclick="apprAct(\''+kind+'\',\''+id+'\',false)">✕ Reject</button>'
    : '<span class="pill p-nu" style="padding:7px 12px">View only — you don\'t have approval rights</span>';
  return '<div class="mini" style="margin-top:10px"><h4>Decision</h4>'+
    (canW?'<textarea id="apprNote" placeholder="Optional note / reason…" style="width:100%;min-height:56px;border:1px solid var(--line);border-radius:8px;padding:8px;font-family:inherit;font-size:13px;resize:vertical"></textarea>':'')+
    '<div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">'+
      buttons+
      '<a class="btn" href="'+erp+'" target="_blank" rel="noopener">↗ Open in ERP</a>'+
      '<button class="btn" onclick="closeModal()" style="margin-left:auto">Close</button>'+
    '</div>'+
    '<div id="apprMsg" class="note-s"></div></div>';
}
function apprAct(kind,id,approve){
  var word=approve?'APPROVE':'REJECT';
  var note=(document.getElementById('apprNote')&&document.getElementById('apprNote').value)||'';
  var msg=document.getElementById('apprMsg');
  if(!window.confirm('Confirm: '+word+' '+id+'? This writes to the ERP and cannot be undone here.'))return;
  if(msg){msg.textContent='Submitting '+word.toLowerCase()+'…';}
  var u='/api/method/md_approvals_api?action='+(approve?'approve':'reject')+'&kind='+kind+'&name='+encodeURIComponent(id)+'&note='+encodeURIComponent(note);
  fetch(u,{headers:{'Accept':'application/json'},credentials:'same-origin'})
    .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
    .then(function(j){
      var d=j.message||j;
      if(d && d.ok){
        toast('Done',id+' → '+d.new_state);
        closeModal();
        loadApprovals(false);
      } else {
        if(msg){msg.textContent='Server did not confirm the change.';}
      }
    })
    .catch(function(err){ if(msg){msg.textContent='Failed: '+err.message+' (check your role / that the doc is still pending).';} });
}

