/* map an accounts branch label to the GST payload key (Branch spelling) */
function gstKey(branch){
  if(!GST.on||!GST.data) return '';
  if(GST.data[branch]) return branch;
  var nb=norm(branch);
  for(var k in GST.data){ if(GST.data.hasOwnProperty(k)){ if(norm(k)===nb) return k; } }
  return '';
}
function gstModal(key){
  var modes=GST.data[key]; if(!modes) return;
  var rows=[]; var tG=0,tN=0,tT=0,tNew=0,tOld=0;
  for(var m in modes){ if(modes.hasOwnProperty(m)){
    var x=modes[m];
    var gross=x.total||0, net=x.net||0, gst=x.gst||0, ns=x.new_sale||0, os=x.old_sale||0;
    rows.push({c:[m,money(gross),money(net),money(gst),money(ns),money(os)]});
    tG+=gross; tN+=net; tT+=gst; tNew+=ns; tOld+=os;
  }}

  var mediaHtml='';
  if(MSALE.on){
    var mmap=null;
    if(MSALE.data[key]) mmap=MSALE.data[key];
    else { var nk=norm(key); for(var bk in MSALE.data){ if(MSALE.data.hasOwnProperty(bk)){ if(norm(bk)===nk){ mmap=MSALE.data[bk]; } } } }
    if(mmap){
      var mrows=[]; var gG=0,gC=0,gNew=0,gOld=0,gInv=0;
      for(var md in mmap){ if(mmap.hasOwnProperty(md)){
        var y=mmap[md];
        var mg=y.gross||0, mc=y.coll||0, mn=y.new_sale||0, mo=y.old_sale||0, mi=y.invoices||0;
        mrows.push({c:[md,money(mg),money(mc),money(mn),money(mo),mi]});
        gG+=mg; gC+=mc; gNew+=mn; gOld+=mo; gInv+=mi;
      }}
      mediaHtml='<div style="margin-top:18px;font-weight:600;color:#0F3D1E">Media-wise Sale</div>'+
        table([{t:'Media'},{t:'Package Amount',num:1},{t:'Collected',num:1},{t:'New Sale',num:1},{t:'Old Sale',num:1},{t:'Invoices',num:1}],
          mrows,['TOTAL',money(gG),money(gC),money(gNew),money(gOld),gInv])+
        '<div class="note-s">Package Amount = SI grand total by posting date. Collected = Payment Entry allocated in range. Media taken from Patient, else Therapy Plan. New = billed &amp; paid same day; Old = collected against a prior invoice.</div>';
    } else {
      mediaHtml='<div class="note-s" style="margin-top:14px">No media-wise data for this branch in range.</div>';
    }
  } else {
    mediaHtml='<div class="note-s" style="margin-top:14px">Loading media split…</div>';
  }

  openModal('Collections GST Split — '+key,
    '<div class="mstat">'+
      '<div><div class="l">Package Amount</div><div class="v">'+money(tG)+'</div></div>'+
      '<div><div class="l">Net (without GST)</div><div class="v">'+money(tN)+'</div></div>'+
      '<div><div class="l">GST</div><div class="v">'+money(tT)+'</div></div>'+
      '<div><div class="l">New Sale</div><div class="v">'+money(tNew)+'</div></div>'+
      '<div><div class="l">Old Sale</div><div class="v">'+money(tOld)+'</div></div>'+
    '</div>'+
    table([{t:'Payment Mode'},{t:'Package Amount',num:1},{t:'Net',num:1},{t:'GST',num:1},{t:'New Sale',num:1},{t:'Old Sale',num:1}],
      rows,['TOTAL',money(tG),money(tN),money(tT),money(tNew),money(tOld)])+
    '<div class="note-s">Real GST computed per invoice tax ratio (not a flat ÷1.05). New sale = invoice &amp; payment on the same date (billed &amp; paid same day); old sale = payment received on a later date against a prior invoice (collected pending amount).</div>'+
    mediaHtml);
}
function accClusterTbl(){
  if(!ACC.clusters.length) return emptyBox('No cluster data.');
  return table([{t:'Cluster'},{t:'Head(s)'},{t:'Target',num:1},{t:'Achieved',num:1},{t:'Ach %',num:1},{t:'Coll (GST)',num:1},{t:'Coll (Net)',num:1}],
    ACC.clusters.map(function(c){return {c:[c.name,c.heads,mL(c.target),mL(c.achieved),
      '<span class="pill '+(c.pct>=100?'p-ok':c.pct>=80?'p-wn':'p-al')+'">'+pc(c.pct,0)+'</span>',
      mL(c.coll_gst),mL(c.coll_net)]};}));
}

/* ============================================================
