   ============================================================ */
function pgCluster(){
  if(!ACC.on&&!BR.length) return phead('Cluster Monitoring','Telangana vs Andhra.')+sec('Clusters','',emptyBox('Loading…'));
  var cards='<div class="split">'+CLUSTERS.map(function(cl){
    var accCl=null; for(var i=0;i<ACC.clusters.length;i++){if(ACC.clusters[i].id===cl.id)accCl=ACC.clusters[i];}
    var bs=BR.filter(function(b){return b.cl===cl.id;});
    var rev=bs.reduce(function(s,b){return s+b.gsale;},0);
    var coll=bs.reduce(function(s,b){return s+b.coll;},0);
    var dues=bs.reduce(function(s,b){return s+b.duesAmt;},0);
    return '<div class="mini">'+
      '<h4 style="cursor:pointer" onclick="clusterModal(\''+cl.id+'\')">'+cl.name+' <em>'+bs.length+' branches ›</em></h4>'+
      '<div class="note-s" style="margin:0 0 9px 0">Head(s): <b>'+cl.heads.join(', ')+'</b></div>'+
      '<div class="mstat" style="grid-template-columns:1fr 1fr">'+
        '<div><div class="l">Revenue</div><div class="v">'+mL(rev)+'</div></div>'+
        '<div><div class="l">Collected</div><div class="v">'+mL(coll)+'</div></div>'+
        (accCl?'<div><div class="l">Target</div><div class="v">'+mL(accCl.target)+'</div></div>'+
        '<div><div class="l">Ach %</div><div class="v">'+pc(accCl.pct,0)+'</div></div>':
        '<div><div class="l">Dues</div><div class="v">'+mL(dues)+'</div></div>')+
      '</div>'+
      table([{t:'Branch'},{t:'Revenue',num:1},{t:'Coll',num:1},{t:'Dues',num:1}],
        bs.sort(function(a,b){return b.gsale-a.gsale;}).map(function(b){return {click:"branchModal('"+b.c+"')",
          c:[b.n,mL(b.gsale),mL(b.coll),mL(b.duesAmt)]};}))+
      '<div style="margin-top:8px"><button class="btn sm gold" onclick="clusterModal(\''+cl.id+'\')">Full cluster detail ›</button></div>'+
    '</div>';}).join('')+'</div>';

  var cmp=[];
  CLUSTERS.forEach(function(cl){
    var bs=BR.filter(function(b){return b.cl===cl.id;});
    cmp.push({l:cl.id,v:Math.round(bs.reduce(function(s,b){return s+b.gsale;},0)/100000),c:cl.id==='AP'?'#2A5D7C':'#2E7D51'});
  });

  return phead('Cluster Monitoring',
    'Side-by-side health of the Telangana and Andhra clusters — revenue, collections and (where target sheets exist) achievement against target.')
   +sec('Cluster Comparison','Package amount, ₹ lakhs',barChart(cmp,{h:200}),'blue')
   +sec('Cluster Detail','Each cluster with its branches · click a header for full modal',cards);
}
function clusterModal(clid){
  var cl=null; for(var i=0;i<CLUSTERS.length;i++){if(CLUSTERS[i].id===clid)cl=CLUSTERS[i];}
  if(!cl)return;
  var accCl=null; for(var j=0;j<ACC.clusters.length;j++){if(ACC.clusters[j].id===clid)accCl=ACC.clusters[j];}
  var bs=BR.filter(function(b){return b.cl===clid;});
  var rev=bs.reduce(function(s,b){return s+b.gsale;},0);
  var coll=bs.reduce(function(s,b){return s+b.coll;},0);
  var dues=bs.reduce(function(s,b){return s+b.duesAmt;},0);
  var inv=bs.reduce(function(s,b){return s+(b.inv||0);},0);
  var stat='<div class="mstat">'+
    '<div><div class="l">Revenue</div><div class="v">'+money(rev)+'</div></div>'+
    '<div><div class="l">Collected</div><div class="v">'+money(coll)+'</div></div>'+
    '<div><div class="l">Outstanding</div><div class="v">'+money(dues)+'</div></div>'+
    '<div><div class="l">Invoices</div><div class="v">'+inv+'</div></div>'+
    (accCl?'<div><div class="l">Target</div><div class="v">'+money(accCl.target)+'</div></div>'+
    '<div><div class="l">Achievement</div><div class="v">'+pc(accCl.pct,0)+'</div></div>':'')+
  '</div>';
  // per-branch table incl target/achievement from ACC.targets
  var rows=bs.sort(function(a,b){return b.gsale-a.gsale;}).map(function(b){
    var at=null; for(var k=0;k<ACC.targets.length;k++){ if(norm(ACC.targets[k].branch)===norm(b.n)) at=ACC.targets[k]; }
    return {click:"closeModal();branchModal('"+b.c+"')",c:[b.n,mL(b.gsale),mL(b.coll),mL(b.duesAmt),
      at?mL(at.target):'—', at?'<span class="pill '+(at.pct>=100?'p-ok':at.pct>=80?'p-wn':'p-al')+'">'+pc(at.pct,0)+'</span>':'—']};});
  openModal(cl.name+' <span style="font-size:13px;opacity:.8">· '+cl.heads.join(', ')+'</span>',
    stat+
    '<div class="mini"><h4>Cluster Head(s)</h4><div style="font-size:15px"><b>'+cl.heads.join(', ')+'</b></div>'+
    '<div class="note-s">'+bs.length+' branches. Collections are live from Payment Entry. Targets from the weekly target sheets overlapping the selected cycle.</div></div>'+
    table([{t:'Branch'},{t:'Revenue',num:1},{t:'Collected',num:1},{t:'Dues',num:1},{t:'Target',num:1},{t:'Ach %',num:1}],
      rows,['TOTAL',mL(rev),mL(coll),mL(dues),accCl?mL(accCl.target):'—',accCl?pc(accCl.pct,0):'—'])+
    '<div class="note-s">Click any branch row for its full card.</div>');
}

