   ============================================================ */
function pgForecast(){
  if(!FCAST.on) return phead('Forecast','Cycle projection and next-cycle forecast.')+
    sec('Forecast','',emptyBox('Loading… if this stays, install md_forecast_api.'));
  var c=FCAST.cycle, nx=FCAST.next;
  var revPace=c.rev_projected>=(c.rev_sofar||0)?'':'';
  var kp='<div class="kgrid">'+
    kpi('Package Amount — this cycle',mC(c.rev_sofar||0),c.elapsed+' of '+c.total_days+' days','b','',"fcastModal('rev_cycle')")+
    kpi('Projected at cycle end',mC(c.rev_projected||0),'At current run rate','g','<span class="kt u">proj</span>',"fcastModal('rev_cycle')")+
    kpi('Collections — this cycle',mC(c.coll_sofar||0),'From Payment Entry','b','',"fcastModal('coll_cycle')")+
    kpi('Projected collections',mC(c.coll_projected||0),c.days_left+' days left','g','<span class="kt u">proj</span>',"fcastModal('coll_cycle')")+
  '</div>';

  // cycle projection callout
  var proj='<div class="split">'+
    '<div class="mini"><h4>Package Amount projection</h4>'+
      '<div style="font-family:Georgia,serif;font-size:26px;color:var(--deep)">'+mC(c.rev_projected||0)+'</div>'+
      '<div class="note-s">'+mC(c.rev_sofar||0)+' booked in '+c.elapsed+' days · run rate '+mL(c.rev_run_rate||0)+'/day × '+c.days_left+' days left</div>'+
      barpc((c.rev_sofar||0),(c.rev_projected||1))+'</div>'+
    '<div class="mini"><h4>Collections projection</h4>'+
      '<div style="font-family:Georgia,serif;font-size:26px;color:var(--deep)">'+mC(c.coll_projected||0)+'</div>'+
      '<div class="note-s">'+mC(c.coll_sofar||0)+' collected · run rate '+mL(c.coll_run_rate||0)+'/day × '+c.days_left+' days left</div>'+
      barpc((c.coll_sofar||0),(c.coll_projected||1))+'</div>'+
  '</div>';

  // next-cycle forecast
  var nfc='<div class="split">'+
    '<div class="mini" style="cursor:pointer" onclick="fcastModal(\'rev_next\')"><h4>Next cycle — package amount <em>forecast ›</em></h4>'+
      '<div style="font-family:Georgia,serif;font-size:26px;color:var(--forest)">'+mC(nx.rev_forecast||0)+'</div>'+
      '<div class="note-s">Recency-weighted from last '+(nx.rev_series||[]).length+' months (simple avg '+mC(nx.rev_simple_avg||0)+')</div>'+
      forecastSpark(nx.rev_series,nx.rev_forecast)+'</div>'+
    '<div class="mini" style="cursor:pointer" onclick="fcastModal(\'coll_next\')"><h4>Next cycle — collections <em>forecast ›</em></h4>'+
      '<div style="font-family:Georgia,serif;font-size:26px;color:var(--forest)">'+mC(nx.coll_forecast||0)+'</div>'+
      '<div class="note-s">Recency-weighted (simple avg '+mC(nx.coll_simple_avg||0)+')</div>'+
      forecastSpark(nx.coll_series,nx.coll_forecast)+'</div>'+
  '</div>';

  var method='<div class="note-s" style="line-height:1.7">'+
    '<b>Cycle projection</b> = booked so far + (daily run rate × days left in the 6th→5th cycle). '+
    '<b>Next-cycle forecast</b> = recency-weighted average of the last 6 months (recent months weighted higher) plus half the average month-over-month change — stable but responsive to momentum. Forecasts are directional, not guarantees.</div>';

  return phead('Forecast',
    'Where this cycle lands at the current pace, and what next cycle looks like based on the last six months. Package amount from Sales Invoices, collections from Payment Entry.')
   +kp
   +sec('This Cycle — Projection to Cycle End','Run-rate based',proj,'gold')
   +sec('Next Cycle — Trend Forecast','Recency-weighted',nfc,'plum')
   +sec('Method','How these numbers are built',method,'blue');
}
function forecastSpark(series,fc){
  series=series||[];
  if(!series.length) return emptyBox('Not enough history.');
  var vals=series.map(function(s){return s.value/100000;});
  vals.push((fc||0)/100000);
  var labels=series.map(function(s){return s.label.split(' ')[0];});
  labels.push('Fcst');
  return lineChart([{d:vals,c:'#6B4A75',fill:'#B89AD6'}],labels,{h:150});
}
function fcastModal(which){
  var c=FCAST.cycle, nx=FCAST.next;
  var title,body;
  if(which==='rev_cycle'||which==='coll_cycle'){
    var isRev=(which==='rev_cycle');
    var sofar=isRev?c.rev_sofar:c.coll_sofar;
    var proj=isRev?c.rev_projected:c.coll_projected;
    var rate=isRev?c.rev_run_rate:c.coll_run_rate;
    var label=isRev?'Package Amount':'Collections';
    title=label+' — Cycle Projection';
    body='<div class="mstat">'+
      '<div><div class="l">Booked so far</div><div class="v">'+money(sofar)+'</div></div>'+
      '<div><div class="l">Projected (cycle end)</div><div class="v">'+money(proj)+'</div></div>'+
      '<div><div class="l">Daily run rate</div><div class="v">'+money(rate)+'</div></div>'+
      '<div><div class="l">Days elapsed</div><div class="v">'+c.elapsed+' / '+c.total_days+'</div></div>'+
      '<div><div class="l">Days left</div><div class="v">'+c.days_left+'</div></div>'+
    '</div>'+
    '<div class="tgt-need '+(proj>=sofar?'ok':'warn')+'">'+
      '<div class="l">Projected total by '+c.to+'</div>'+
      '<div class="v" style="color:var(--pos)">'+money(proj)+'</div>'+
      '<div class="s">'+money(sofar)+' booked in '+c.elapsed+' days, continuing at '+money(rate)+'/day for '+c.days_left+' more day'+(c.days_left===1?'':'s')+'</div>'+
    '</div>'+
    '<div class="mini"><h4>How this projection works</h4>'+
    '<div class="note-s" style="line-height:1.8">This is a straight <b>run-rate projection</b> for the current 6th→5th cycle:<br>'+
    '<b>Projected = booked so far + (daily run rate × days left)</b><br>'+
    'Daily run rate = '+money(sofar)+' ÷ '+c.elapsed+' elapsed days = <b>'+money(rate)+'/day</b><br>'+
    'Remaining = '+money(rate)+' × '+c.days_left+' days = <b>'+money(rate*c.days_left)+'</b><br>'+
    'It assumes the rest of the cycle continues at the same pace as so far — it does not model month-end surges or slow starts. '+(isRev?'Package amount is from submitted Sales Invoices.':'Collections are from Payment Entry received.')+'</div></div>';
  } else {
    var isRevN=(which==='rev_next');
    var fc=isRevN?nx.rev_forecast:nx.coll_forecast;
    var savg=isRevN?nx.rev_simple_avg:nx.coll_simple_avg;
    var series=isRevN?nx.rev_series:nx.coll_series;
    var labelN=isRevN?'Package Amount':'Collections';
    title=labelN+' — Next-Cycle Forecast';
    var histRows=(series||[]).map(function(s){return {c:[s.label,money(s.value)]};});
    var diff=fc-savg;
    body='<div class="mstat">'+
      '<div><div class="l">Forecast (next cycle)</div><div class="v" style="color:var(--forest)">'+money(fc)+'</div></div>'+
      '<div><div class="l">Simple average</div><div class="v">'+money(savg)+'</div></div>'+
      '<div><div class="l">Trend adjustment</div><div class="v" style="color:'+(diff>=0?'var(--pos)':'var(--alert)')+'">'+(diff>=0?'+':'')+money(diff)+'</div></div>'+
      '<div><div class="l">Months used</div><div class="v">'+(series||[]).length+'</div></div>'+
    '</div>'+
    forecastSpark(series,fc)+
    '<div class="mini"><h4>How this forecast works</h4>'+
    '<div class="note-s" style="line-height:1.8">Two-part method, tuned for data with steady month-to-month momentum:<br>'+
    '<b>1. Recency-weighted average</b> — the last '+(series||[]).length+' months, with the most recent month weighted heaviest (weights 1, 2, 3… so newer months matter more than old ones). This gives a base of <b>'+money(fc-((fc-savg)))+'</b>-ish before trend.<br>'+
    '<b>2. Trend nudge</b> — plus half the average month-over-month change, so a rising or falling trajectory is reflected without over-reacting to one spike.<br>'+
    'The <b>simple average ('+money(savg)+')</b> is shown alongside as a sanity check — if the forecast is far from it, momentum is strong. Forecasts are directional guidance, not commitments.</div></div>'+
    sec('Months used','Actuals feeding the forecast',table([{t:'Month'},{t:'Actual',num:1}],histRows,['FORECAST',money(fc)]));
  }
  openModal(title,body+'<div style="margin-top:10px"><button class="btn" onclick="closeModal()">Close</button></div>');
}

