function moveBranch(code,clid){
  CLUSTERS.forEach(function(c){var ix=c.br.indexOf(code);if(ix>-1)c.br.splice(ix,1);});
  var c=null;for(var i=0;i<CLUSTERS.length;i++){if(CLUSTERS[i].id===clid){c=CLUSTERS[i];break;}}
  c.br.push(code);
  for(var j=0;j<BR.length;j++){if(BR[j].c===code){BR[j].cl=clid;BR[j].cluster=c.name;}}
  buildFilters();chips();render();
  toast('Cluster updated',code+' moved to '+c.name+'.');
}
function addHead(ci,name){
  if(!name)return;
  if(CLUSTERS[ci].heads.indexOf(name)<0) CLUSTERS[ci].heads.push(name);
  render();
  toast('Cluster head added',name+' → '+CLUSTERS[ci].name+'.');
}
function removeHead(ci,name){
  var ix=CLUSTERS[ci].heads.indexOf(name);
  if(ix>-1)CLUSTERS[ci].heads.splice(ix,1);
  render();
}

