/* ============================================================
   LIVE DATA LAYER
   ============================================================ */
function apiURL(){
  var u='/api/method/md_command_center_api';
  if(LIVE.from&&LIVE.to) u+='?from_date='+LIVE.from+'&to_date='+LIVE.to;
  return u;
}
function applyLive(d){
  if(!d) return;
  LIVE.on=true; LIVE.from=d.from_date; LIVE.to=d.to_date;
  LIVE.people=d.people||{};
  LIVE.heads=d.branch_heads||{};
  LIVE.areaManagers=d.area_managers||[];
  LIVE.totals=d.totals||{};

  /* ---- build BR fresh from live branches ---- */
  var live=[];
  (d.branches||[]).forEach(function(lb){
    var cc=lb.cc||'';
    if(cc.toLowerCase().indexOf('main')>-1) return;      // skip HO
    if(cc.toLowerCase().indexOf('testing')>-1) return;   // skip test branch
    var m=ccResolve(cc);
    var b={};
    b.cc=cc;
    if(m){ b.c=m[1]; b.cl=m[2]; b.n=m[3]; }
    else { b.c=cleanName(cc).slice(0,3).toUpperCase(); b.cl='TG'; b.n=cleanName(cc); }
   b.gsale=lb.gross||0;
    b.net=lb.net||0;          /* live per-invoice net from server */
    b.coll=lb.coll||0;

    b.duesAmt=lb.out||0;
    b.inv=lb.inv||0;
    b.clients=lb.clients||0;
    b.staff=0; b.staffM=0;
    b.head='';
    live.push(b);
  });
  BR=live;

  /* ---- clusters rebuilt from live codes ---- */
  CLUSTERS.forEach(function(c){ c.br=BR.filter(function(b){return b.cl===c.id;}).map(function(b){return b.c;}); });
  BR.forEach(function(b){ var c=null;for(var i=0;i<CLUSTERS.length;i++){if(CLUSTERS[i].id===b.cl)c=CLUSTERS[i];} b.cluster=c?c.name:'—'; });

  /* ---- branch heads (live, normalised match) ---- */
  BR.forEach(function(b){
    var key=norm(b.n);
    for(var hk in LIVE.heads){ if(LIVE.heads.hasOwnProperty(hk)){
      if(norm(LIVE.heads[hk].branch)===key || hk===key){ b.head=LIVE.heads[hk].name; }
    }}
  });

  /* ---- staff per branch (people keyed by branch name) ---- */
  if(d.people){
    BR.forEach(function(b){
      var key=norm(b.n);
      for(var pk in d.people){ if(d.people.hasOwnProperty(pk)){
        if(norm(pk)===key){ b.staff=d.people[pk].total||0; b.staffM=d.people[pk].male||0; }
      }}
    });
  }

  /* ---- 12-month series ---- */
  SER=(d.series||[]).map(function(s){return {m:s.m,rev:+(s.rev||0),coll:+(s.coll||0)};});

  /* ---- verticals with share % ---- */
  VERT=[];
  var vtot=0; (d.verticals||[]).forEach(function(v){vtot+=v.amt||0;});
  if(vtot>0){ (d.verticals||[]).forEach(function(v){ VERT.push({name:v.name,amt:v.amt||0,sh:(v.amt||0)/vtot*100}); }); }

  /* ---- lead channels with share % ---- */
  CHAN=[];
  var ltot=0; (d.lead_channels||[]).forEach(function(c){ltot+=c.leads||0;});
  if(ltot>0){ (d.lead_channels||[]).forEach(function(c){ CHAN.push({n:c.src,lead:c.leads||0,sh:(c.leads||0)/ltot*100,conv:c.conv||0}); }); }

  /* ---- roles ---- */
  ROLES=(d.roles||[]).map(function(r){return {role:r.role,count:r.count||0};});

  /* ---- top performers ---- */
  TOPPERF=(d.top_performers||[]).map(function(p){
    var m=ccResolve(p.branch);
    return {n:p.name,b:(m?m[1]:cleanName(p.branch)),v:Math.round(p.rev||0),inv:p.inv||0};
  });

  /* ---- attrition into BR ---- */
  (d.attrition||[]).forEach(function(x){
    var m=ccResolve(x.branch); var key=m?norm(m[3]):norm(cleanName(x.branch));
    BR.forEach(function(b){ if(norm(b.n)===key) b.attr=+(x.pct||0); });
  });

  /* ---- approvals ---- */
  APPR=[];
  var disc=(d.approvals&&d.approvals.discount&&d.approvals.discount.pending)||[];
  disc.forEach(function(x){
    var risk=x.pct>=25?'high':x.pct>=15?'med':'low';
    var m=ccResolve(x.branch||x.invoice||'');
    APPR.push({id:x.id,t:'Discount Approval',b:(x.branch||(m?m[1]:'—')),cl:(x.by||'—'),
      det:(x.level?x.level+' · ':'')+'Discount '+(x.pct||0)+'% on '+(x.invoice||'invoice')+(x.reason?' — '+x.reason:''),
      amt:x.bill||0,by:x.approver||x.by||'—',risk:risk,stage:x.level});
  });
  var p2p=(d.approvals&&d.approvals.p2p&&d.approvals.p2p.pending)||[];
  p2p.forEach(function(x){
    APPR.push({id:x.id,t:'Plan Conversion (P2P)',b:x.branch||'—',cl:x.client||'—',
      det:'Same-client package conversion'+(x.stage?' · '+x.stage:''),amt:x.amount||0,by:'Branch → Audit → COO',
      risk:(x.amount>=200000?'high':'med'),stage:x.stage});
  });
  var c2c=(d.approvals&&d.approvals.c2c&&d.approvals.c2c.pending)||[];
  c2c.forEach(function(x){
    APPR.push({id:x.id,t:'Client Transfer (C2C)',b:x.branch||'—',cl:x.client||'—',
      det:'Client-to-client transfer'+(x.to_branch&&x.to_branch!==x.branch?' → '+x.to_branch:''),amt:x.amount||0,
      by:'Branch → Audit → COO',risk:'med',stage:x.stage});
  });
}

