function loadLive(showToast){
  liveBanner('⟳ Loading live data…','warn');
  fetch(apiURL(),{headers:{'Accept':'application/json'},credentials:'same-origin'})
    .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
    .then(function(j){
      var d=j.message||j;
      applyLive(d);
      buildFilters(); buildMenu(); chips(); render();
    //   liveBanner('● LIVE · '+d.from_date+' → '+d.to_date+' · ₹'+((d.totals.gross||0)/100000).toFixed(1)+'L gross · '+(d.totals.approvals_pending||0)+' approvals','ok');
      if(showToast) toast('Live data loaded',BR.length+' branches · '+(d.totals.invoices||0)+' invoices · '+(d.totals.approvals_pending||0)+' approvals pending');
    })
    .catch(function(err){
      liveBanner('● Core API unreachable ('+err.message+') — no data to show','err');
      buildFilters(); buildMenu(); chips(); render();
    });
  loadModules();
}

