/* ---- generic module fetch; re-renders if the user is on that page ---- */
var mdModuleErrors={};
function fetchModule(method,applyFn,pageId){
  delete mdModuleErrors[method];
  var u='/api/method/'+method;
  if(LIVE.from&&LIVE.to) u+='?from_date='+LIVE.from+'&to_date='+LIVE.to;
  fetch(u,{headers:{'Accept':'application/json'},credentials:'same-origin'})
    .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
    .then(function(j){if(j.exc||j.exception)throw Error('ERP lookup failed');applyFn(j.message||j);buildMenu();if(CUR===pageId||CUR==='cluster'||CUR==='score')render();})
    .catch(function(err){mdModuleErrors[method]=true;if(CUR===pageId)render();});
}
function loadModules(){
  fetchModule('md_accounts_api',applyAccounts,'accounts');
  fetchModule('md_stock_api',applyStock,'stock');
  fetchModule('md_hr_api',applyHR,'hr');
