(function(){

    function mdEdgeById(id){
        return document.getElementById(id);
    }

    function mdEdgeEsc(value){
        return String(value == null ? "" : value)
            .replace(/&/g,"&amp;")
            .replace(/</g,"&lt;")
            .replace(/>/g,"&gt;")
            .replace(/"/g,"&quot;");
    }

    function mdEdgeToday(){
        try{
            if(
                window.frappe &&
                frappe.datetime &&
                typeof frappe.datetime.get_today === "function"
            ){
                return frappe.datetime.get_today();
            }
        }catch(e){}

        var now = new Date();
        var local = new Date(now.getTime() - now.getTimezoneOffset()*60000);

        return local.toISOString().slice(0,10);
    }

    function mdEdgeCsrf(){
        if(window.frappe && frappe.csrf_token){
            return frappe.csrf_token;
        }

        var meta = document.querySelector('meta[name="csrf-token"]');
        if(meta) return meta.content || "";

        return "";
    }

    async function mdEdgeGetList(doctype, fields, filters, options){
        options = options || {};

        var params = new URLSearchParams();

        params.set("doctype", doctype);
        params.set("fields", JSON.stringify(fields || ["name"]));

        if(filters){
            params.set("filters", JSON.stringify(filters));
        }

        params.set(
            "limit_page_length",
            String(
                options.limit_page_length == null
                    ? 500
                    : options.limit_page_length
            )
        );

        if(options.order_by){
            params.set("order_by", options.order_by);
        }

        var response = await fetch(
            "/api/method/frappe.client.get_list?" + params.toString(),
            {
                method:"GET",
                credentials:"same-origin",
                headers:{
                    "Accept":"application/json",
                    "X-Frappe-CSRF-Token":mdEdgeCsrf()
                }
            }
        );

        if(!response.ok){
            throw new Error(
                "Could not load " + doctype +
                " (HTTP " + response.status + ")"
            );
        }

        var data = await response.json();

        return Array.isArray(data.message)
            ? data.message
            : [];
    }

    function mdEdgeCloseAll(){
        ["mdEdgeAppointments","mdEdgeFloor"].forEach(function(id){
            var panel = mdEdgeById(id);

            if(panel){
                panel.classList.remove("on");
                panel.setAttribute("aria-hidden","true");
            }
        });

        [
            ["mdEdgeTabAppointments","mdEdgeAppointments"],
            ["mdEdgeTabFloor","mdEdgeFloor"]
        ].forEach(function(pair){
            var button = mdEdgeById(pair[0]);

            if(button){
                button.setAttribute("aria-expanded","false");
            }
        });
    }

    async function mdEdgeOpen(which){
        var isAppointments = which === "appointments";

        var panelId = isAppointments
            ? "mdEdgeAppointments"
            : "mdEdgeFloor";

        var buttonId = isAppointments
            ? "mdEdgeTabAppointments"
            : "mdEdgeTabFloor";

        var panel = mdEdgeById(panelId);
        var button = mdEdgeById(buttonId);

        if(!panel) return;

        var wasOpen = panel.classList.contains("on");

        mdEdgeCloseAll();

        if(wasOpen){
            return;
        }

        panel.classList.add("on");
        panel.setAttribute("aria-hidden","false");

        if(button){
            button.setAttribute("aria-expanded","true");
        }

        if(isAppointments){
            await mdEdgeLoadAppointments();
        }else{
            await mdEdgeLoadFloor();
        }
    }

    function mdEdgeAppointmentTime(row){
        var value =
            row.appointment_time ||
            row.custom_appointment_time ||
            "";

        if(!value) return "—";

        return String(value).slice(0,5);
    }

    async function mdEdgeLoadAppointments(){
        var body = mdEdgeById("mdEdgeAppointmentsBody");
        var count = mdEdgeById("mdEdgeAppointmentsCount");
        var subtitle = mdEdgeById("mdEdgeAppointmentsSub");

        if(!body) return;

        var today = mdEdgeToday();

        if(subtitle){
            subtitle.textContent = "LIVE · " + today;
        }

        body.innerHTML =
            '<div class="md-edge-loading">Loading today’s appointments…</div>';

        try{
            var fields = [
                "name",
                "patient",
                "patient_name",
                "appointment_date",
                "appointment_time",
                "status",
                "department",
                "practitioner",
                "branch"
            ];

            var rows = await mdEdgeGetList(
                "Patient Appointment",
                fields,
                [
                    ["appointment_date","=",today]
                ],
                {
                    limit_page_length:500,
                    order_by:"appointment_time asc"
                }
            );

            rows = rows.filter(function(row){
                var status = String(row.status || "").toLowerCase();

                return (
                    status !== "cancelled" &&
                    status !== "canceled"
                );
            });

            if(count){
                count.textContent = String(rows.length);
            }

            if(!rows.length){
                body.innerHTML =
                    '<div class="md-edge-empty">No appointments found for today.</div>';
                return;
            }

            body.innerHTML = rows.map(function(row){

                var person =
                    row.patient_name ||
                    row.patient ||
                    "Client";

                var meta = [
                    row.branch,
                    row.department,
                    row.practitioner,
                    row.status
                ].filter(Boolean).join(" · ");

                return (
                    '<div class="md-edge-row">' +
                        '<div>' +
                            '<div class="md-edge-row-title">' +
                                mdEdgeEsc(person) +
                            '</div>' +
                            '<div class="md-edge-row-meta">' +
                                mdEdgeEsc(meta || row.name) +
                            '</div>' +
                        '</div>' +
                        '<div class="md-edge-row-time">' +
                            mdEdgeEsc(mdEdgeAppointmentTime(row)) +
                        '</div>' +
                    '</div>'
                );
            }).join("");

        }catch(error){

            void 0;

            if(count){
                count.textContent = "!";
            }

            body.innerHTML =
                '<div class="md-edge-empty">' +
                    mdEdgeEsc(error.message || "Could not load appointments.") +
                '</div>';
        }
    }

    function mdEdgeSupportDepartment(value){
        return String(value || "")
            .replace(/\s*-\s*(LSACPL|LASPL)\s*$/i,"")
            .trim()
            .toLowerCase()
            .includes("support");
    }

    function mdEdgeDateTimeOnly(value){
        if(!value) return "";

        var text = String(value);

        if(text.indexOf(" ") > -1){
            return text.split(" ")[1].slice(0,5);
        }

        if(text.indexOf("T") > -1){
            return text.split("T")[1].slice(0,5);
        }

        return text.slice(-8,-3);
    }

    async function mdEdgeLoadFloor(){
        var body = mdEdgeById("mdEdgeFloorBody");
        var count = mdEdgeById("mdEdgeFloorCount");
        var subtitle = mdEdgeById("mdEdgeFloorSub");

        if(!body) return;

        var today = mdEdgeToday();

        if(subtitle){
            subtitle.textContent =
                "TODAY · SUPPORT · CHECK-IN / CHECK-OUT · " + today;
        }

        body.innerHTML =
            '<div class="md-edge-loading">Loading Support attendance…</div>';

        try{
            var employees = await mdEdgeGetList(
                "Employee",
                [
                    "name",
                    "employee_name",
                    "designation",
                    "department",
                    "branch",
                    "status"
                ],
                [
                    ["status","=","Active"]
                ],
                {
                    limit_page_length:1000,
                    order_by:"employee_name asc"
                }
            );

            employees = employees.filter(function(employee){
                return mdEdgeSupportDepartment(employee.department);
            });

            var checkinOK=true,attendanceOK=true;var checkins = await mdEdgeGetList(
                "Employee Checkin",
                [
                    "employee",
                    "employee_name",
                    "time",
                    "log_type"
                ],
                [
                    ["time","between",[
                        today + " 00:00:00",
                        today + " 23:59:59"
                    ]]
                ],
                {
                    limit_page_length:2000,
                    order_by:"time asc"
                }
            ).catch(function(){checkinOK=false;return []});
var attendance=await mdEdgeGetList("Attendance",["employee","status","custom_check_in_time","custom_check_out_time","in_time","out_time","modified"],[["attendance_date","=",today],["docstatus","!=",2]],{limit_page_length:2000,order_by:"modified desc"}).catch(function(){attendanceOK=false;return []});if(!checkinOK&&!attendanceOK)throw Error('Attendance sources unavailable');
var byEmployee = {};

            checkins.forEach(function(row){
                var key = String(row.employee || "").trim();

                if(!key) return;

                if(!byEmployee[key]){
                    byEmployee[key] = [];
                }

                byEmployee[key].push(row);
            });

            var prepared=employees.map(function(employee){var logs=byEmployee[employee.name]||[],latest=logs[logs.length-1],firstIn=logs.find(function(l){return l.log_type==='IN'}),lastOut=logs.filter(function(l){return l.log_type==='OUT'}).pop(),a=attendance.find(function(a){return a.employee===employee.name}),pin=a&&(a.custom_check_in_time||a.in_time),pout=a&&(a.custom_check_out_time||a.out_time),state;if(latest)state=latest.log_type==='IN'?'on-floor':latest.log_type==='OUT'?'checked-out':'unverified';else if(pin&&!pout)state='on-floor';else if(pin&&pout&&String(pout)>String(pin))state='checked-out';else if(pin||(a&&['Present','Half Day','Work From Home'].includes(a.status)))state='unverified';else state=checkinOK&&attendanceOK?'not-checked-in':'unverified';return {name:employee.employee_name||employee.name,designation:employee.designation||'',branch:employee.branch||'',state:state,inTime:firstIn?mdEdgeDateTimeOnly(firstIn.time):pin?(String(pin).match(/\d{1,2}:\d{2}/)||['—'])[0]:'',outTime:lastOut?mdEdgeDateTimeOnly(lastOut.time):pout?(String(pout).match(/\d{1,2}:\d{2}/)||['—'])[0]:''}});
var onFloor = prepared.filter(function(row){
                return row.state === "on-floor";
            }).length;

            var checkedOut = prepared.filter(function(row){
                return row.state === "checked-out";
            }).length;

            var notIn = prepared.filter(function(row){
                return row.state === "not-checked-in";
            }).length;

            if(count){
                count.textContent = String(onFloor);
            }

            prepared.sort(function(a,b){
                var order = {
                    "on-floor":0,
                    "checked-out":1,
                    "unverified":2,"not-checked-in":3
                };

                return (
                    order[a.state] - order[b.state] ||
                    a.name.localeCompare(b.name)
                );
            });

            var summary =
                '<div class="md-edge-summary">' +
                    '<div class="md-edge-stat"><b>' + onFloor + '</b><span>On Floor</span></div>' +
                    '<div class="md-edge-stat"><b>' + checkedOut + '</b><span>Checked Out</span></div>' +
                    '<div class="md-edge-stat"><b>' + notIn + '</b><span>No Check-in</span></div>' + '<div class="md-edge-stat"><b>'+prepared.filter(function(r){return r.state==="unverified"}).length+'</b><span>Unverified</span></div>' +
                '</div>';

            if(!prepared.length){
                body.innerHTML =
                    summary +
                    '<div class="md-edge-empty">No active Support employees found.</div>';
                return;
            }

            body.innerHTML =
                summary +
                prepared.map(function(row){

                    var statusText =
                        row.state === "on-floor"
                            ? "ON FLOOR"
                            : row.state === "checked-out"
                                ? "CHECKED OUT"
                                : row.state === "unverified" ? "STATUS UNVERIFIED" : "NOT CHECKED IN";

                    var statusClass =
                        row.state === "checked-out"
                            ? " out"
                            : row.state === "not-checked-in"
                                ? " off"
                                : row.state === "unverified" ? " unverified" : "";

                    var timeText =
                        row.state === "on-floor"
                            ? (row.inTime ? "IN " + row.inTime : "")
                            : row.state === "checked-out"
                                ? (
                                    (row.inTime ? "IN " + row.inTime : "") +
                                    (row.outTime ? " · OUT " + row.outTime : "")
                                  )
                                : "—";

                    var meta = [
                        row.designation,
                        row.branch
                    ].filter(Boolean).join(" · ");

                    return (
                        '<div class="md-edge-row">' +
                            '<div>' +
                                '<div class="md-edge-row-title">' +
                                    mdEdgeEsc(row.name) +
                                '</div>' +
                                '<div class="md-edge-row-meta">' +
                                    mdEdgeEsc(meta || "Support") +
                                '</div>' +
                                '<span class="md-edge-status' +
                                    statusClass +
                                '">' +
                                    statusText +
                                '</span>' +
                            '</div>' +
                            '<div class="md-edge-row-time">' +
                                mdEdgeEsc(timeText) +
                            '</div>' +
                        '</div>'
                    );
                }).join("");

        }catch(error){

            void 0;

            if(count){
                count.textContent = "!";
            }

            body.innerHTML =
                '<div class="md-edge-empty">' +
                    mdEdgeEsc(error.message || "Could not load Support attendance.") +
                '</div>';
        }
    }

    function mdEdgeBind(){
        var appointments = mdEdgeById("mdEdgeTabAppointments");
        var floor = mdEdgeById("mdEdgeTabFloor");

        if(appointments && appointments.dataset.mdEdgeBound !== "1"){
            appointments.dataset.mdEdgeBound = "1";

            appointments.addEventListener("click",function(event){
                event.preventDefault();
                event.stopPropagation();

                mdEdgeOpen("appointments");
            });
        }

        if(floor && floor.dataset.mdEdgeBound !== "1"){
            floor.dataset.mdEdgeBound = "1";

            floor.addEventListener("click",function(event){
                event.preventDefault();
                event.stopPropagation();

                mdEdgeOpen("floor");
            });
        }

        document
            .querySelectorAll("[data-md-edge-close]")
            .forEach(function(button){

                if(button.dataset.mdEdgeBound === "1"){
                    return;
                }

                button.dataset.mdEdgeBound = "1";

                button.addEventListener("click",function(event){
                    event.preventDefault();
                    event.stopPropagation();

                    mdEdgeCloseAll();
                });
            });
    }

    if(document.readyState === "loading"){
        document.addEventListener(
            "DOMContentLoaded",
            mdEdgeBind,
            {once:true}
        );
    }else{
        mdEdgeBind();
    }

    setTimeout(mdEdgeBind,250);
    setTimeout(mdEdgeBind,1200);

    window.MD_EDGE_OPEN_APPOINTMENTS = function(){
        return mdEdgeOpen("appointments");
    };

    window.MD_EDGE_OPEN_FLOOR = function(){
        return mdEdgeOpen("floor");
    };

    window.MD_EDGE_CLOSE_ALL = mdEdgeCloseAll;

