(function(){function init(){var main=document.querySelector('.main'),sidebar=document.querySelector('.sidebar');if(!main)return;function decorate(){var page=(main.querySelector('h1')||{}).textContent||'Dashboard',key='md-premium-layout:'+page,settings;try{settings=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){settings={}}var sections=Array.from(main.querySelectorAll('.sec'));sections.forEach(function(sec){var h=sec.querySelector(':scope>header'),title=h&&h.querySelector('h3');if(!h||!title||h.querySelector('.md-panel-tools'))return;var name=title.textContent;sec.dataset.mdPanel=name;if(settings.collapsed&&settings.collapsed.includes(name))sec.classList.add('closed');var tools=document.createElement('span');tools.className='md-panel-tools';[['up','↑'],['down','↓']].forEach(function(a){var button=document.createElement('button');button.type='button';button.textContent=a[1];button.title='Move '+a[0]+': '+name;button.setAttribute('aria-label',button.title);button.onclick=function(e){e.stopPropagation();var parent=sec.parentElement,list=Array.from(parent.children).filter(x=>x.classList.contains('sec')),i=list.indexOf(sec);if(a[0]==='up'&&i>0)parent.insertBefore(sec,list[i-1]);if(a[0]==='down'&&i<list.length-1)parent.insertBefore(list[i+1],sec);save()};tools.appendChild(button)});h.insertBefore(tools,h.querySelector('.cv'));h.addEventListener('click',save);h.tabIndex=0;h.addEventListener('keydown',function(e){if(e.target===h&&(e.key==='Enter'||e.key===' ')){e.preventDefault();sec.classList.toggle('closed');save()}})});if(settings.order)settings.order.forEach(function(name){var s=sections.find(s=>s.dataset.mdPanel===name);if(s)s.parentElement.appendChild(s)});function save(){var s=Array.from(main.querySelectorAll('.sec'));try{localStorage.setItem(key,JSON.stringify({order:s.map(s=>s.dataset.mdPanel),collapsed:s.filter(s=>s.classList.contains('closed')).map(s=>s.dataset.mdPanel)}))}catch(e){}}}decorate();new MutationObserver(function(changes){if(changes.some(c=>Array.from(c.addedNodes).some(n=>n.nodeType===1&&((n.matches('.sec')&&!n.querySelector('.md-panel-tools'))||Array.from(n.querySelectorAll('.sec')).some(s=>!s.querySelector('.md-panel-tools'))))))decorate()}).observe(main,{childList:true,subtree:true});if(sidebar){var tip=document.createElement('div');tip.className='md-tooltip';tip.hidden=true;document.body.appendChild(tip);sidebar.addEventListener('mouseover',function(e){var item=e.target.closest('.mi');if(!item||!sidebar.classList.contains('mini'))return;tip.textContent=(item.querySelector('.tx')||item).textContent.trim().replace(/[★☆]/g,'');tip.hidden=false;var box=item.getBoundingClientRect();tip.style.left=box.right+9+'px';tip.style.top=Math.min(box.top,innerHeight-tip.offsetHeight-8)+'px'});sidebar.addEventListener('mouseout',function(){tip.hidden=true});sidebar.addEventListener('scroll',function(){tip.hidden=true})}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();
